(window.CLAVE_ARTF=window.CLAVE_ARTF||{})[11]=[["Artículo 1 — Objeto de la ley","<p><b>a)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\"><u class=\"m-clave\">Adaptar</u> el <u class=\"m-clave\">ordenamiento jurídico español al Reglamento</u></mark> (<mark class=\"m-personalizado\">UE</mark>) <mark class=\"m-personalizado\">2016/679</mark> del <mark class=\"m-autoridad\">Parlamento</mark> Europeo y el <mark class=\"m-autoridad\">Consejo,</mark> de 27 de abril de 2016, relativo a la <mark class=\"m-personalizado\">protección de las personas físicas</mark> en lo que respecta <mark class=\"m-personalizado\">al tratamiento de sus datos personales y a la libre circulación</mark> de estos datos, <mark class=\"m-personalizado\">y completar sus disposiciones</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1009\">🎯 1 pregunta</mark></p><p><b>b)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-resp r-ia\" data-q=\"11-ia-1018,11-ia-1040\">Garantizar los derechos digitales de la ciudadanía conforme al mandato establecido</mark> en <mark class=\"m-personalizado\">el artículo 18.4 de la</mark> Constitución.</span></span></p>"],["Artículo 2 — Ámbito de aplicación de los Títulos I a IX y de los artículos 89 a 94","<p><b>b)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">A los</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1022,11-ia-1042,11-ia-1100\">tratamientos de datos de personas fallecidas, sin perjuicio de lo establecido</mark> en el <mark class=\"m-personalizado\">artículo 3.</mark></span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1041,11-ia-1103,11-ia-2042\">🎯 3 preguntas</mark></p><p class=\"ex-mas\"><mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1044\">🎯 1 pregunta más de este artículo</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 3 — Datos de las personas fallecidas <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Como</mark> <mark class=\"m-destacable\">excepción</mark>, las personas a las que se refiere el <mark class=\"m-personalizado\">párrafo anterior no</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">acceder a los datos</mark> del causante, <mark class=\"m-personalizado\">ni solicitar su rectificación o supresión</mark>, <mark class=\"m-personalizado\">cuando la persona fallecida lo</mark> <mark class=\"m-destacable\">hubiese prohibido expresamente</mark> <mark class=\"m-personalizado\">o así lo establezca una ley</mark>. Dicha prohibición <mark class=\"m-personalizado\">no</mark> <mark class=\"m-accion\">afectará</mark> al derecho de los herederos a acceder a los <mark class=\"m-personalizado\">datos <u class=\"m-clave\">de</u> carácter patrimonial del causante</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1046\">🎯 1 pregunta</mark></p><p><mark class=\"m-resp\" data-q=\"11-129,11-ia-1047,11-ia-1133\">Mediante real decreto</mark> <mark class=\"m-accion\">se establecerán</mark> <mark class=\"m-destacable\">los requisitos y condiciones</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">para acreditar la validez y vigencia de estos mandatos e instrucciones</mark> y, en su caso, el <mark class=\"m-personalizado\">registro de los mismos</mark></span></span> . (…)</p>"],["Artículo 4 — Exactitud de los datos <span class=\"ex-sello ex-sello-r\">R2</span> <span class=\"ex-sello ex-sello-r\">R5</span>","<p data-r=\"R2\"><span class=\"ex-sello ex-sello-r\">R2</span> <b>a)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Hubiesen <mark class=\"m-personalizado\">sido obtenidos por</mark> el <mark class=\"m-resp r-ia\" data-q=\"11-ia-1050\">responsable directamente del afectado. b) Hubiesen sido obtenidos</mark> <mark class=\"m-personalizado\">por el responsable de un mediador</mark> <mark class=\"m-destacable\">o</mark> <mark class=\"m-personalizado\">intermediario en caso de que las normas aplicables</mark> al sector de actividad al que pertenezca el responsable del tratamiento <mark class=\"m-personalizado\">establecieran la posibilidad</mark> de intervención de un <mark class=\"m-personalizado\">intermediario o mediador</mark> que recoja en nombre propio los datos de los <mark class=\"m-personalizado\">afectados</mark> para su transmisión al responsable. <mark class=\"m-personalizado\">El mediador</mark> o intermediario <mark class=\"m-accion\">asumirá</mark> <mark class=\"m-personalizado\">las responsabilidades</mark> que pudieran derivarse en el supuesto de comunicación al responsable de datos que no se correspondan con los facilitados por el afectado. c) <mark class=\"m-personalizado\">Fuesen sometidos a</mark> tratamiento por el <mark class=\"m-personalizado\">responsable por haberlos recibido de otro responsable en</mark> virtud del ejercicio por el afectado del derecho a <mark class=\"m-personalizado\">la portabilidad</mark> conforme al artículo 20 del Reglamento (UE) 2016/679 y lo previsto en esta ley orgánica. d) <mark class=\"m-personalizado\">Fuesen obtenidos de un registro público por el responsable</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1043,11-ia-1073,11-ia-1086,11-ia-1279,11-ia-1630\">🎯 5 preguntas</mark></p>"],["Artículo 5 — Deber de confidencialidad","<p><b>3.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Las obligaciones</mark> establecidas en los apartados anteriores <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">mantendrán</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1051,11-ia-1109,11-ia-1777\">aun cuando hubiese finalizado la relación del obligado con el responsable o encargado del tratamiento</mark>.</span></span></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 6 — Tratamiento basado en el consentimiento del afectado <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b>1.</b> <u class=\"m-clave\">De</u> conformidad <span class=\"ex-plg\"><span class=\"ex-plg-t\">con lo dispuesto en el artículo 4.11 del Reglamento (UE) 2016/679, se</span></span> entiende <mark class=\"m-accion\">por</mark> <mark class=\"m-resp\" data-q=\"11-119,11-ia-1024\">consentimiento del afectado</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">toda manifestación de voluntad libre</mark>, <mark class=\"m-destacable\">específica</mark>, <mark class=\"m-destacable\">informada e inequívoca</mark> <mark class=\"m-personalizado\">por la que este acepta</mark>, ya sea <mark class=\"m-personalizado\">mediante una</mark> <mark class=\"m-destacable\">declaración</mark> <mark class=\"m-personalizado\">o una</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">clara</u></mark> <mark class=\"m-personalizado\">acción afirmativa</mark>, <mark class=\"m-personalizado\">el tratamiento de datos</mark> personales que le conciernen.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1052\">🎯 1 pregunta</mark></p><p><b>3.</b> <mark class=\"m-personalizado\">No</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1021,11-ia-1053,11-ia-1894\">supeditarse la ejecución del contrato a que el afectado consienta el tratamiento de los datos personales para finalidades que no guarden relación con el mantenimiento, desarrollo</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">o control de la relación contractual</mark></span></span> .</p>"],["Artículo 7 — Consentimiento de los menores de edad <span class=\"ex-sello ex-sello-r\">R1</span>","<p data-r=\"R1\"><span class=\"ex-sello ex-sello-r\">R1</span> <b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">El tratamiento</mark> de los datos personales de un menor de edad <mark class=\"m-personalizado\">únicamente</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">fundarse en su consentimiento cuando sea mayor de</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1055,11-ia-1524\">catorce años</mark>.</span></span></p><p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">El tratamiento</mark> de los datos de los <span class=\"m-circulo\"><mark class=\"m-destacable\">menores</mark></span> <mark class=\"m-destacable\">de catorce</mark> <mark class=\"m-personalizado\">años</mark>, fundado en el <mark class=\"m-personalizado\">consentimiento</mark>, <mark class=\"m-personalizado\">solo</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">lícito si <u class=\"m-clave\">consta</u> el del titular de</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">la patria</mark></span> <mark class=\"m-personalizado\">potestad o tutela</mark>, <mark class=\"m-resp r-ia\" data-q=\"11-ia-1056\">con el alcance que determinen los titulares de la patria potestad o tutela</mark>.</span></span></p>"],["Artículo 11 — Transparencia e información al afectado","<p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><b><mark class=\"m-personalizado\">a)</mark></b> <mark class=\"m-personalizado\">La identidad</mark> del <mark class=\"m-destacable\">responsable</mark> del tratamiento <mark class=\"m-destacable\">y de su representante</mark>, en su caso. b) <mark class=\"m-personalizado\">La</mark> finalidad del tratamiento. c) La <mark class=\"m-personalizado\">posibilidad de ejercer los</mark> derechos establecidos en los artículos 15 a 22 del Reglamento (UE) 2016/679.</span></span> <mark class=\"m-resp ex-q\" data-q=\"11-236,11-ia-1064\">🎯 2 preguntas</mark></p><p class=\"ex-mas\"><mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1063\">🎯 1 pregunta más de este artículo</mark></p>"],["Artículo 34 — Designación de un delegado de protección de datos","<p><b>a)</b> Los <mark class=\"m-personalizado\"><u class=\"m-clave\">colegios</u> profesionales y sus consejos generales</mark>. <mark class=\"m-resp ex-q\" data-q=\"11-237\">🎯 1 pregunta</mark></p><p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><b><mark class=\"m-personalizado\">c)</mark></b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Las</u> entidades que exploten redes y presten <u class=\"m-clave\">servicios</u> de <u class=\"m-clave\">comunicaciones electrónicas conforme</u> a lo</mark> dispuesto en su legislación específica, <mark class=\"m-personalizado\"><u class=\"m-clave\">cuando</u> traten habitual y sistemáticamente</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">datos</u></mark> personales <mark class=\"m-personalizado\">a gran escala</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1117\">🎯 1 pregunta</mark></p><p><b>d)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Los prestadores de servicios de la sociedad de la información</mark> <mark class=\"m-destacable\">cuando</mark> <mark class=\"m-personalizado\">elaboren a gran escala perfiles</mark> de los usuarios del servicio.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1119\">🎯 1 pregunta</mark></p><p><b>f)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Los establecimientos financieros de crédito</mark>. g) Las <mark class=\"m-personalizado\">entidades <u class=\"m-clave\">aseguradoras y</u> reaseguradoras</mark>. h) <mark class=\"m-personalizado\">Las empresas de servicios <u class=\"m-clave\">de</u> inversión</mark>, <mark class=\"m-personalizado\">reguladas por</mark> la legislación del <mark class=\"m-autoridad\">Mercado de</mark> <mark class=\"m-personalizado\">Valores</mark>. i) <mark class=\"m-personalizado\">Los distribuidores y comercializadores de energía <u class=\"m-clave\">eléctrica</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">y</mark></span> los distribuidores y comercializadores de gas <mark class=\"m-personalizado\">natural</mark>. j) <mark class=\"m-personalizado\">Las entidades</mark> responsables de ficheros comunes para la <mark class=\"m-personalizado\">evaluación de la solvencia patrimonial y <u class=\"m-clave\">crédito</u> o de los ficheros comunes para la gestión y prevención del fraude</mark>, incluyendo a los responsables de los ficheros regulados por la legislación de <mark class=\"m-personalizado\">prevención del blanqueo</mark> de capitales y <mark class=\"m-personalizado\">de la financiación del <u class=\"m-clave\">terrorismo</u></mark>. k) <mark class=\"m-personalizado\">Las entidades</mark> que desarrollen actividades <mark class=\"m-personalizado\">de <u class=\"m-clave\">publicidad</u> y prospección comercial</mark>, incluyendo las de <mark class=\"m-personalizado\">investigación comercial y de mercados</mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">cuando</u></mark> lleven a cabo tratamientos <mark class=\"m-destacable\">basados</mark> en <mark class=\"m-personalizado\">las preferencias</mark> <mark class=\"m-destacable\">de</mark> los <mark class=\"m-destacable\">afectados</mark> o <mark class=\"m-destacable\">realicen</mark> actividades que impliquen la <mark class=\"m-personalizado\">elaboración de perfiles</mark> de los mismos. l) <mark class=\"m-personalizado\">Los centros sanitarios legalmente obligados</mark> al mantenimiento de las <mark class=\"m-personalizado\">historias clínicas</mark> de los pacientes. <mark class=\"m-personalizado\">Se exceptúan</mark> los profesionales de la salud que, aun <mark class=\"m-personalizado\">estando legalmente obligados</mark> al mantenimiento de las historias clínicas de los pacientes, <mark class=\"m-personalizado\">ejerzan su actividad a título individual</mark>. m) <mark class=\"m-personalizado\">Las entidades</mark> que tengan como uno de sus <mark class=\"m-personalizado\">objetos la emisión de informes comerciales</mark> que puedan referirse <mark class=\"m-personalizado\">a personas físicas</mark>. n) <mark class=\"m-personalizado\">Los operadores</mark> que desarrollen la actividad de <mark class=\"m-personalizado\">juego a</mark> través de <mark class=\"m-personalizado\">canales electrónicos</mark>, <mark class=\"m-personalizado\">informáticos</mark>, <mark class=\"m-personalizado\">telemáticos e interactivos</mark>, <span class=\"m-caja\">conforme</span> a la normativa de <mark class=\"m-autoridad\">regulación del juego</mark>. ñ) <mark class=\"m-personalizado\">Las empresas de seguridad privada</mark>. o) <mark class=\"m-personalizado\">Las federaciones deportivas cuando traten datos de</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1118\">menores de edad</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1116,11-ia-1304\">🎯 2 preguntas</mark></p><p>(…) <b>3.</b> <mark class=\"m-autoridad\">Los responsables y encargados</mark> del tratamiento <mark class=\"m-accion\">comunicarán</mark> en el plazo de <mark class=\"m-resp r-ia\" data-q=\"11-ia-1120\">diez días</mark> a <mark class=\"m-autoridad\">la Agencia Española</mark> de Protección de Datos <mark class=\"m-autoridad\">o, en su caso</mark>, <mark class=\"m-autoridad\">a las autoridades autonómicas</mark> de protección de datos, las <mark class=\"m-personalizado\">designaciones</mark>, <mark class=\"m-personalizado\">nombramientos</mark> y ceses de los <mark class=\"m-autoridad\">delegados</mark> de protección de datos tanto en los supuestos en que se encuentren obligadas a su designación como en el <mark class=\"m-destacable\">caso en que sea voluntaria</mark>. (…) <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1121\">🎯 1 pregunta</mark></p>"],["Artículo 36 — Posición del delegado de protección de datos <span class=\"ex-sello ex-sello-r\">R6</span>","<p data-r=\"R6\"><span class=\"ex-sello ex-sello-r\">R6</span> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><b><mark class=\"m-destacable\">1.</mark></b> <mark class=\"m-destacable\">El</mark> <mark class=\"m-autoridad\">delegado</mark> de protección de datos <mark class=\"m-accion\">actuará</mark> como interlocutor del responsable o encargado del tratamiento ante la Agencia Española de Protección de Datos <mark class=\"m-autoridad\">y las autoridades autonómicas</mark> de protección de datos. El <mark class=\"m-autoridad\">delegado</mark> <mark class=\"m-accion\">podrá inspeccionar</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">los procedimientos relacionados con el objeto de la presente ley orgánica y emitir recomendaciones</u></mark> en el ámbito de sus competencias.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1123\">🎯 1 pregunta</mark></p><p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Cuando</mark> se trate de <mark class=\"m-personalizado\">una <u class=\"m-clave\">persona física integrada en la organización del responsable o encargado del tratamiento</u></mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">el</u></mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">delegado</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">de protección de</u> datos no</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ser removido ni sancionado por el responsable o el encargado por desempeñar sus <u class=\"m-clave\">funciones</u></mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1033,11-ia-1124\">salvo que incurriera en dolo o negligencia grave en su ejercicio</mark>. <mark class=\"m-personalizado\"><u class=\"m-clave\">Se</u></mark> <mark class=\"m-accion\">garantizará</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">la independencia</u></mark> <mark class=\"m-destacable\">del</mark> <mark class=\"m-autoridad\">delegado</mark> <mark class=\"m-destacable\">de protección de datos dentro de la organización</mark>, <mark class=\"m-destacable\">debiendo evitarse cualquier conflicto de intereses</mark>.</span></span></p><p><b>3.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">En el ejercicio de sus funciones el <mark class=\"m-autoridad\">delegado</mark> de protección de datos <mark class=\"m-accion\">tendrá</mark> acceso a los datos personales y procesos de tratamiento, no pudiendo <mark class=\"m-personalizado\">oponer</mark> a este acceso <mark class=\"m-autoridad\">el</mark> responsable o el encargado del tratamiento la <mark class=\"m-personalizado\">existencia</mark> de cualquier <mark class=\"m-personalizado\">deber de confidencialidad o secreto</mark>, incluyendo el previsto en el artículo 5 de esta ley orgánica.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1125\">🎯 1 pregunta</mark></p><p><b>4.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Cuando</mark> el <mark class=\"m-autoridad\">delegado de protección</mark> de datos <mark class=\"m-personalizado\">aprecie</mark> la existencia de una <mark class=\"m-destacable\">vulneración relevante</mark> en materia de protección de datos <mark class=\"m-personalizado\">lo</mark> <mark class=\"m-accion\">documentará</mark> <mark class=\"m-personalizado\">y lo</mark> <mark class=\"m-accion\">comunicará</mark> <mark class=\"m-personalizado\">inmediatamente a los</mark> <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-personalizado\">de administración y dirección del</mark> <mark class=\"m-autoridad\">responsable o el encargado</mark> del tratamiento.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1126\">🎯 1 pregunta</mark></p>"],["Artículo 52 — Deber de colaboración","<p><span class=\"ex-plg\"><span class=\"ex-plg-t\">(…) <b>3.</b> <mark class=\"m-personalizado\">Cuando no</mark> haya <mark class=\"m-personalizado\">podido realizar la identificación <u class=\"m-clave\">por</u> otros medios</mark>, la Agencia Española de Protección de Datos <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">recabar</mark> de los <mark class=\"m-autoridad\">operadores</mark> que presten servicios <mark class=\"m-autoridad\">de comunicaciones electrónicas</mark> disponibles al público <mark class=\"m-personalizado\">y</mark> de <mark class=\"m-autoridad\">los prestadores de servicios de la sociedad de la información</mark> <mark class=\"m-personalizado\">los datos</mark> que obren en su poder y que <mark class=\"m-personalizado\">resulten imprescindibles para la identificación</mark> del presunto responsable de la conducta contraria al Reglamento (UE) 2016/679 y a la presente ley orgánica <mark class=\"m-personalizado\">cuando</mark> se hubiere <mark class=\"m-personalizado\">llevado a cabo mediante</mark> la utilización de un <mark class=\"m-personalizado\">servicio de la sociedad de la información o</mark> la realización de una <mark class=\"m-personalizado\">comunicación electrónica</mark>. <mark class=\"m-personalizado\">A tales efectos</mark>, <mark class=\"m-personalizado\">los datos</mark> que la Agencia Española de Protección de <mark class=\"m-personalizado\">Datos</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">recabar al</mark> amparo de este apartado <mark class=\"m-personalizado\">son los siguientes</mark>:</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1166,11-ia-1245\">🎯 2 preguntas</mark></p><p><b>3.º</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">El nombre</mark>, <mark class=\"m-personalizado\">número de documento identificativo y dirección del abonado o</mark> del usuario registrado al que se le hubiera asignado la <mark class=\"m-personalizado\">dirección de Protocolo de Internet</mark> a la que se refieren los dos párrafos <mark class=\"m-personalizado\">anteriores</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1167\">🎯 1 pregunta</mark></p><p><mark class=\"m-personalizado\">Estos datos</mark> <mark class=\"m-accion\">deberán</mark> <mark class=\"m-personalizado\">ser cedidos</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, <mark class=\"m-personalizado\">previo requerimiento motivado</mark> de la Agencia Española de Protección de Datos, <mark class=\"m-personalizado\">exclusivamente en el marco</mark> de actuaciones de <mark class=\"m-personalizado\">investigación</mark></span></span> iniciadas <mark class=\"m-personalizado\">como consecuencia de una</mark> <mark class=\"m-resp\" data-q=\"11-125\">denuncia presentada por un afectado respecto de una conducta de una persona jurídica o respecto a la utilización de sistemas que permitan la divulgación sin restricciones</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">de datos personales</mark>. <mark class=\"m-personalizado\">En el resto de</mark> los supuestos la cesión de estos datos</span></span> <mark class=\"m-accion\">requerirá</mark> la <mark class=\"m-resp r-ia\" data-q=\"11-ia-1168,11-ia-1297\">previa obtención de <mark class=\"m-destacable\">autorización judicial</mark> otorgada conforme a las normas procesales cuando resultara exigible</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1039\">🎯 1 pregunta</mark></p><p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Quedan excluidos</mark> de lo previsto en este apartado los <mark class=\"m-personalizado\">datos de tráfico</mark> que los operadores estuviesen tratando con la exclusiva finalidad de dar cumplimiento a las obligaciones previstas en la Ley 25/2007, de 18 de octubre, <mark class=\"m-personalizado\">de conservación de datos relativos a las comunicaciones electrónicas</mark> y a las redes públicas de comunicaciones, cuya cesión solamente <mark class=\"m-accion\">podrá tener</mark> lugar <mark class=\"m-resp r-ia\" data-q=\"11-ia-1169\">de acuerdo con lo dispuesto en ella, <mark class=\"m-personalizado\">previa autorización judicial</mark> solicitada por alguno de los agentes facultados</mark> a los que se refiere el artículo 6 de dicha ley.</span></span></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 53 — Alcance de la actividad de investigación <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Quienes desarrollen la actividad de investigación <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">recabar las informaciones precisas para el <u class=\"m-clave\">cumplimiento de</u> sus funciones</mark>, realizar <mark class=\"m-personalizado\">inspecciones</mark>, <mark class=\"m-personalizado\">requerir la exhibición o el envío de los documentos y datos</mark> necesarios, <mark class=\"m-personalizado\">examinarlos</mark> en el lugar en que se encuentren depositados o en donde <mark class=\"m-personalizado\">se</mark> lleven <mark class=\"m-personalizado\">a</mark> cabo los tratamientos, <mark class=\"m-personalizado\">obtener copia</mark> de ellos, <mark class=\"m-personalizado\">inspeccionar los equipos</mark> físicos y lógicos y <mark class=\"m-personalizado\">requerir la ejecución de tratamientos y programas</mark> o procedimientos de gestión y soporte del tratamiento sujetos a investigación.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1172\">🎯 1 pregunta</mark></p><p><b>2.</b> Cuando fuese <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">necesario el acceso</mark> por el personal que desarrolla la actividad <mark class=\"m-personalizado\">de investigación al</mark> <mark class=\"m-destacable\">domicilio constitucionalmente protegido</mark> del inspeccionado,</span></span> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">preciso</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1170\">contar con su consentimiento o haber obtenido la correspondiente autorización judicial</mark>.</p><p><b>3.</b> <mark class=\"m-personalizado\">Cuando se trate de</mark> <mark class=\"m-autoridad\">órganos</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">judiciales</mark> u oficinas judiciales el ejercicio de las facultades <mark class=\"m-personalizado\">de inspección</mark></span></span> <mark class=\"m-accion\">se efectuará</mark> <mark class=\"m-personalizado\">a través <u class=\"m-clave\">y</u> por mediación del</mark> <mark class=\"m-resp\" data-q=\"11-146,11-ia-1171\">Consejo General del Poder Judicial</mark>.</p>"],["Artículo 65 — Admisión a trámite de las reclamaciones <span class=\"ex-sello ex-sello-r\">R9</span>","<p data-r=\"R9\"><span class=\"ex-sello ex-sello-r\">R9</span> <span class=\"ex-plg\"><span class=\"ex-plg-t\">(…) <b><mark class=\"m-personalizado\">2.</mark></b> La Agencia Española de Protección de Datos <mark class=\"m-accion\">inadmitirá</mark> <mark class=\"m-personalizado\">las</mark> reclamaciones <mark class=\"m-autoridad\">presentadas cuando</mark> no <mark class=\"m-resp r-ia\" data-q=\"11-ia-1197,11-ia-1703\">versen sobre cuestiones de protección de datos personales, carezcan manifiestamente de fundamento, sean abusivas o no aporten indicios racionales de la existencia</mark> <mark class=\"m-personalizado\">de una infracción</mark>.</span></span></p><p>(…) <b>5.</b> <mark class=\"m-personalizado\">La decisión sobre la</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">admisión o inadmisión</u> a</mark> trámite, así como la que determine, en <mark class=\"m-personalizado\">su caso</mark>, <mark class=\"m-personalizado\">la remisión de la</mark> reclamación <mark class=\"m-personalizado\">a la</mark> <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-personalizado\">de control principal</mark> que se estime competente, <mark class=\"m-accion\">deberá</mark> <mark class=\"m-destacable\">notificarse al</mark> <mark class=\"m-autoridad\">reclamante en el plazo de tres</mark> <mark class=\"m-personalizado\">meses</mark>. <mark class=\"m-personalizado\">Si transcurrido este plazo</mark> no se produjera dicha notificación, <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-personalizado\">que</mark> <mark class=\"m-destacable\">prosigue</mark> <mark class=\"m-personalizado\">la tramitación de la reclamación</mark> con arreglo a lo dispuesto en este título <mark class=\"m-personalizado\">a partir de la fecha en que</mark> se <mark class=\"m-resp r-ia\" data-q=\"11-ia-1198\">cumpliesen tres meses desde que la reclamación tuvo entrada en la Agencia Española de Protección de Datos, sin perjuicio de la facultad de la Agencia de archivar posteriormente y de forma expresa</mark> la reclamación.</p>"],["Artículo 73 — Infracciones consideradas graves","<p>En función de lo que establece el artículo 83.4 del Reglamento (UE) 2016/679 se consideran graves y <mark class=\"m-accion\">prescribirán</mark> <mark class=\"m-plazo\">a los</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1212,11-ia-1217,11-ia-2159,11-ia-2169\">dos años</mark> las infracciones que supongan una <mark class=\"m-personalizado\">vulneración sustancial</mark> de los artículos mencionados en aquel y, en particular, <mark class=\"m-personalizado\">las siguientes</mark>:</p><p><b>u)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">El <mark class=\"m-personalizado\">tratamiento</mark> de datos personales <mark class=\"m-personalizado\">sin haber consultado previamente a la</mark> <mark class=\"m-autoridad\">autoridad</mark> de protección de datos en los casos en que <mark class=\"m-personalizado\">dicha consulta resulta preceptiva</mark> conforme al artículo 36 del Reglamento (UE) 2016/679 o cuando la ley establezca la obligación de llevar a cabo esa consulta.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1225\">🎯 1 pregunta</mark></p><p><b>v)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">El incumplimiento de la obligación de <u class=\"m-clave\">designar</u> un</mark> <mark class=\"m-autoridad\">delegado</mark> <mark class=\"m-personalizado\">de protección</mark> de datos cuando <mark class=\"m-personalizado\">sea exigible su nombramiento</mark> de acuerdo con el artículo 37 del Reglamento (UE) 2016/679 y el artículo 34 de esta ley orgánica.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1216\">🎯 1 pregunta</mark></p>"],["Artículo 75 — Interrupción de la prescripción de la infracción","<p><mark class=\"m-accion\">Interrumpirá</mark> <mark class=\"m-personalizado\">la prescripción la iniciación</mark>, <mark class=\"m-personalizado\">con conocimiento del interesado</mark>, <mark class=\"m-personalizado\">del procedimiento sancionador</mark>, <mark class=\"m-personalizado\">reiniciándose</mark> el plazo de prescripción si el expediente sancionador estuviere <mark class=\"m-personalizado\">paralizado</mark> <mark class=\"m-plazo\">durante más</mark> <mark class=\"m-autoridad\">de</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1195,11-ia-1226\">seis meses por causas no imputables al presunto infractor</mark>.</p><p><span class=\"ex-plg\"><span class=\"ex-plg-t\">Cuando la Agencia Española de Protección de Datos ostente la condición de <mark class=\"m-autoridad\">autoridad</mark> de control principal y deba seguirse el procedimiento previsto en el artículo 60 del Reglamento (UE) 2016/679 <mark class=\"m-accion\">interrumpirá</mark> <mark class=\"m-personalizado\">la prescripción el <mark class=\"m-resp r-ia\" data-q=\"11-ia-1227\">conocimiento formal por el interesado del acuerdo de inicio</mark></mark>.</span></span></p>"],["Artículo 76 — Sanciones y medidas correctivas","<p>(…) <b>4.</b> <mark class=\"m-accion\">Será</mark> objeto de <mark class=\"m-destacable\">publicación</mark> en el <mark class=\"m-personalizado\">Boletín Oficial del</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">la información</mark> que identifique <mark class=\"m-personalizado\">al infractor</mark>, <mark class=\"m-personalizado\">la infracción</mark> cometida <span class=\"m-circulo\"><mark class=\"m-personalizado\">y</mark></span> <mark class=\"m-personalizado\">el importe</mark> de la <mark class=\"m-resp r-ia\" data-q=\"11-ia-1231,11-ia-1813\">sanción impuesta cuando la autoridad competente sea la Agencia Española de Protección de Datos, la sanción fuese superior a un millón de euros</mark> y el infractor <mark class=\"m-personalizado\">sea</mark> una <mark class=\"m-destacable\"><u class=\"m-clave\">persona</u> jurídica</mark>.</p><p class=\"ex-mas\"><mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1230\">🎯 1 pregunta más de este artículo</mark></p>"],["Artículo 77 — Régimen aplicable a determinadas categorías de responsables o encargados del tratamiento","<p><span class=\"ex-plg\"><span class=\"ex-plg-t\">(…) <b>3.</b> Sin perjuicio de lo establecido en el apartado anterior, <mark class=\"m-autoridad\">la autoridad de protección</mark> de datos <mark class=\"m-accion\">propondrá</mark> también <mark class=\"m-personalizado\">la iniciación de actuaciones</mark> <mark class=\"m-destacable\">disciplinarias</mark> cuando existan indicios suficientes para ello. En este caso, <mark class=\"m-personalizado\">el procedimiento y las sanciones</mark> a aplicar <mark class=\"m-accion\">serán</mark> las establecidas en la legislación sobre <mark class=\"m-personalizado\">régimen disciplinario</mark> o sancionador que resulte <mark class=\"m-personalizado\">de aplicación</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1239\">🎯 1 pregunta</mark></p><p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Asimismo</mark>, cuando <mark class=\"m-personalizado\">las infracciones</mark> sean imputables a <mark class=\"m-autoridad\">autoridades</mark> <mark class=\"m-personalizado\">y directivos</mark>, <mark class=\"m-personalizado\">y</mark> se acredite la <mark class=\"m-personalizado\">existencia de informes técnicos o recomendaciones</mark> para el tratamiento que <mark class=\"m-personalizado\">no</mark> hubieran sido debidamente <mark class=\"m-personalizado\">atendidos</mark>, en <mark class=\"m-destacable\">la resolución</mark> en la que se imponga la sanción se <mark class=\"m-resp r-ia\" data-q=\"11-ia-1237,11-ia-1994,11-ia-2108\">incluirá una amonestación con denominación del cargo responsable y se ordenará la publicación en el Boletín Oficial del Estado o autonómico</mark> que corresponda. (…)</span></span></p><p class=\"ex-mas\"><mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1236\">🎯 1 pregunta más de este artículo</mark></p>"],["Artículo 78 — Prescripción de las sanciones <span class=\"ex-sello ex-sello-r\">R10</span>","<p><b>c)</b> <mark class=\"m-personalizado\">Las sanciones</mark> por un importe <mark class=\"m-personalizado\">superior a <mark class=\"m-resp r-ia\" data-q=\"11-ia-1242\">300.000 euros</mark></mark> prescriben a <mark class=\"m-plazo\">los tres años</mark>.</p><p><b>3.</b> <mark class=\"m-personalizado\">La prescripción</mark> <mark class=\"m-accion\">se interrumpirá</mark> <mark class=\"m-personalizado\">por la iniciación</mark>, <mark class=\"m-personalizado\">con conocimiento del interesado</mark>, <mark class=\"m-personalizado\">del procedimiento de</mark> <mark class=\"m-destacable\">ejecución</mark>, <mark class=\"m-personalizado\">volviendo a transcurrir el</mark> plazo si el mismo <mark class=\"m-personalizado\">está paralizado</mark> <mark class=\"m-plazo\">durante más de seis meses por causa</mark> <mark class=\"m-personalizado\">no imputable al infractor</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1244\">🎯 1 pregunta</mark></p>"],["Artículo 88 — Derecho a la desconexión digital en el ámbito laboral","<p><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Los trabajadores y los empleados públicos</mark> <mark class=\"m-accion\">tendrán</mark> <mark class=\"m-personalizado\">derecho a la desconexión digital a fin de garantizar</mark>, fuera del tiempo de trabajo legal o convencionalmente establecido, <mark class=\"m-personalizado\">el respeto de su tiempo de descanso</mark>, <mark class=\"m-personalizado\">permisos y vacaciones</mark>, así como de su <mark class=\"m-personalizado\">intimidad personal y familiar</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1261\">🎯 1 pregunta</mark></p><p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Las modalidades de ejercicio</mark> de este derecho <mark class=\"m-accion\">atenderán</mark> <mark class=\"m-personalizado\">a la naturaleza y objeto de la relación laboral</mark>, <mark class=\"m-accion\">potenciarán</mark> el derecho a la conciliación de la actividad laboral y la vida personal y familiar <mark class=\"m-personalizado\">y se</mark> <mark class=\"m-accion\">sujetarán</mark> <mark class=\"m-personalizado\">a lo establecido en la negociación colectiva o,</mark> en su defecto, a lo <mark class=\"m-personalizado\">acordado entre la empresa y los representantes</mark> de los trabajadores.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1262\">🎯 1 pregunta</mark></p><p><b>3.</b> <mark class=\"m-personalizado\">El empleador</mark>, <mark class=\"m-resp\" data-q=\"11-163,11-ia-1017,11-ia-1141,11-ia-1772,11-ia-2173\">previa audiencia de los representantes de los trabajadores, elaborará una política interna dirigida a trabajadores, incluidos los que ocupen puestos directivos, en la que definirán las modalidades de ejercicio del derecho</mark> a <span class=\"ex-plg\"><span class=\"ex-plg-t\">la desconexión y las acciones de formación y de sensibilización del personal sobre un uso razonable de las herramientas tecnológicas que evite el <mark class=\"m-destacable\">riesgo de <mark class=\"m-resp r-ia\" data-q=\"11-ia-1263\">fatiga informática</mark></mark>. <mark class=\"m-personalizado\">En particular</mark>, <mark class=\"m-accion\">se preservará</mark> el derecho a la desconexión digital en los supuestos de <mark class=\"m-personalizado\">realización total o parcial del trabajo a distancia</mark> así como en el domicilio del empleado vinculado al uso con fines laborales de <mark class=\"m-personalizado\">herramientas tecnológicas</mark></span></span> . <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1329\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 89 — Derecho a la intimidad frente al uso de dispositivos de videovigilancia y de grabación de sonidos en el lugar de trabajo <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><span class=\"ex-plg\"><span class=\"ex-plg-t\">En el supuesto de que se haya <mark class=\"m-personalizado\">captado la</mark> <mark class=\"m-autoridad\">comisión</mark> <mark class=\"m-personalizado\">flagrante de un acto ilícito</mark> <mark class=\"m-autoridad\">por los trabajadores</mark> o los <mark class=\"m-autoridad\">empleados públicos</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-personalizado\">cumplido <u class=\"m-clave\">el</u> deber de informar</mark> cuando existiese <mark class=\"m-personalizado\">al menos</mark> el dispositivo al que se refiere <mark class=\"m-personalizado\">el artículo 22.4</mark> de esta ley orgánica.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1264\">🎯 1 pregunta</mark></p><p><b>3.</b> La utilización <span class=\"ex-plg\"><span class=\"ex-plg-t\">de sistemas similares a los referidos en los apartados anteriores para la grabación de <mark class=\"m-destacable\">sonidos</mark> <mark class=\"m-personalizado\">en el lugar de trabajo se</mark></span></span> <mark class=\"m-accion\">admitirá</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">únicamente cuando</u></mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1101\">resulten relevantes los riesgos para la seguridad de las instalaciones, bienes y personas derivados de la actividad que se desarrolle en el centro de trabajo y siempre respetando</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">el principio de proporcionalidad</mark>, <mark class=\"m-destacable\">el de intervención mínima y las garantías previstas en los apartados anteriores</mark>. <mark class=\"m-destacable\">La supresión de los sonidos conservados por estos sistemas de grabación se</mark> <mark class=\"m-accion\">realizará</mark> <mark class=\"m-destacable\">atendiendo a lo dispuesto en el apartado 3 del artículo</mark> 22 de <mark class=\"m-destacable\">esta ley</mark></span></span> . <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1266\">🎯 1 pregunta</mark></p>"],["Artículo 19 — Comparecencia de las personas <span class=\"ex-sello ex-sello-r\">R16</span>","<p data-r=\"R16\"><span class=\"ex-sello ex-sello-r\">R16</span> <b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">La comparecencia</mark> de <mark class=\"m-personalizado\">las personas</mark> ante las <mark class=\"m-autoridad\">oficinas públicas</mark>, ya sea <mark class=\"m-personalizado\">presencialmente</mark> o <mark class=\"m-destacable\">por</mark> medios <mark class=\"m-personalizado\">electrónicos</mark>, <mark class=\"m-personalizado\">sólo</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">obligatoria</mark> cuando así esté <mark class=\"m-resp r-ia\" data-q=\"11-ia-1453\">previsto en una norma con rango</mark> <mark class=\"m-destacable\">de ley</mark>.</span></span></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 20 — Responsabilidad de la tramitación <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b>1.</b> Los <mark class=\"m-autoridad\">titulares</mark> de las <mark class=\"m-resp\" data-q=\"11-145,11-ia-1265,11-ia-1455\">unidades administrativas y el personal al servicio de las Administraciones Públicas que tuviesen a su cargo la resolución o el despacho</mark> de <span class=\"ex-plg\"><span class=\"ex-plg-t\">los <mark class=\"m-destacable\">asuntos</mark>, <mark class=\"m-accion\">serán</mark> <mark class=\"m-autoridad\">responsables</mark> <mark class=\"m-personalizado\">directos</mark> de su <mark class=\"m-destacable\">tramitación</mark> y <mark class=\"m-accion\">adoptarán</mark> las <mark class=\"m-personalizado\">medidas oportunas</mark> para <mark class=\"m-accion\">remover</mark> los <mark class=\"m-destacable\">obstáculos</mark> que <mark class=\"m-accion\">impidan</mark>, <mark class=\"m-destacable\">dificulten</mark> o <mark class=\"m-destacable\">retrasen</mark> el <mark class=\"m-personalizado\">ejercicio</mark> <mark class=\"m-autoridad\">pleno</mark> de los</span></span></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 21 — Obligación de resolver <span class=\"ex-sello\">EX</span> <span class=\"ex-sello ex-sello-r\">R17</span> <span class=\"ex-sello ex-sello-r\">R18</span></div><div class=\"ex-fb\"><p data-r=\"R18\"><span class=\"ex-sello ex-sello-r\">R18</span> <mark class=\"m-personalizado\">Este plazo no</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">exceder de</mark> <mark class=\"m-resp\" data-q=\"11-192,11-ia-1458\">seis meses salvo que una norma con rango de Ley establezca uno mayor o así venga previsto en el Derecho</mark> <mark class=\"m-personalizado\">de la</mark> <mark class=\"m-autoridad\">Unión</mark> Europea.</p><p><mark class=\"m-personalizado\">En todo caso</mark>, las Administraciones Públicas <mark class=\"m-accion\">informarán</mark> <mark class=\"m-personalizado\">a</mark> los interesados <mark class=\"m-personalizado\">del plazo máximo</mark> establecido para la resolución de los procedimientos y para la notificación de los actos que les pongan término, así como de los efectos que pueda producir el silencio administrativo. Dicha mención <mark class=\"m-accion\">se incluirá</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en la notificación o publicación del acuerdo de iniciación de oficio, o en la comunicación que <mark class=\"m-accion\">se dirigirá</mark> al efecto al</span></span> interesado <mark class=\"m-plazo\">dentro de los</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1369,11-ia-1460,11-ia-1461,11-ia-1554,11-ia-2087\">diez días siguientes a la recepción de la solicitud iniciadora del procedimiento en el registro electrónico de la Administración u Organismo competente</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\"><u class=\"m-clave\">para su</u> tramitación</mark>. <mark class=\"m-personalizado\">En este último</mark> caso, la comunicación <mark class=\"m-accion\">indicará</mark> además la fecha en que la solicitud ha sido recibida por el <mark class=\"m-autoridad\">órgano</mark> competente.</span></span>  (…)</p><p class=\"ex-mas\"><mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1456\">🎯 1 pregunta más de este artículo</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 22 — Suspensión del plazo máximo para resolver <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b><mark class=\"m-destacable\">d)</mark></b> Cuando se soliciten informes preceptivos a un <mark class=\"m-autoridad\">órgano</mark> de la misma o distinta Administración, por el tiempo que medie entre la petición, que <mark class=\"m-accion\">deberá comunicarse</mark> a los interesados, y la <mark class=\"m-plazo\">recepción del</mark> <mark class=\"m-destacable\">informe</mark>, <mark class=\"m-destacable\">que igualmente</mark> <mark class=\"m-accion\">deberá</mark> <mark class=\"m-destacable\">ser comunicada a los mismos</mark>. <mark class=\"m-destacable\">Este plazo de</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">suspensión no</u></mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">exceder en ningún caso de</u></mark> <mark class=\"m-resp\" data-q=\"11-128,11-ia-1459,11-ia-1465\">tres meses</mark>. <mark class=\"m-personalizado\"><u class=\"m-clave\">En caso de no recibirse el informe en el plazo indicado</u></mark>, <mark class=\"m-accion\">proseguirá</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">el procedimiento</u></mark> .</p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 23 — Ampliación del plazo máximo para resolver y notificar <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b>1.</b> Excepcionalmente, cuando se hayan agotado <mark class=\"m-personalizado\">los</mark> medios personales y materiales disponibles a los <mark class=\"m-personalizado\">que se refiere el apartado 5 del artículo 21,</mark> el <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-destacable\">competente para resolver</mark>, <mark class=\"m-personalizado\">a propuesta</mark>, <span class=\"m-caja\">en</span> su caso, <mark class=\"m-personalizado\">del</mark> <mark class=\"m-autoridad\">órgano</mark> instructor o <mark class=\"m-plazo\">el superior jerárquico</mark> <mark class=\"m-autoridad\">del órgano</mark> <mark class=\"m-plazo\">competente para resolver</mark>, <mark class=\"m-accion\">podrá</mark> <mark class=\"m-plazo\">acordar de</mark> manera motivada <mark class=\"m-plazo\">la ampliación del plazo máximo de resolución y notificación</mark>, <mark class=\"m-plazo\">no pudiendo ser éste superior al establecido</mark> para la <mark class=\"m-plazo\">tramitación del</mark> procedimiento. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1469\">🎯 1 pregunta</mark></p><p><b>2.</b> <mark class=\"m-personalizado\">Contra</mark> el acuerdo que resuelva sobre la <mark class=\"m-personalizado\">ampliación</mark> de plazos, que <mark class=\"m-accion\">deberá</mark> ser notificado a los interesados, no <mark class=\"m-resp\" data-q=\"11-133,11-153,11-ia-1470\">cabrá recurso alguno</mark>.</p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 24 — Silencio administrativo en procedimientos iniciados a solicitud del interesado <span class=\"ex-sello\">EX</span> <span class=\"ex-sello ex-sello-r\">R20</span></div><div class=\"ex-fb\"><p><b>1.</b> En los procedimientos iniciados a solicitud del interesado, sin perjuicio de la resolución que la Administración debe dictar en la forma prevista en el apartado 3 de este artículo, <mark class=\"m-personalizado\">el vencimiento del plazo máximo sin haberse notificado <u class=\"m-clave\">resolución</u> expresa</mark>, legitima al interesado o interesados para entenderla <mark class=\"m-destacable\">estimada</mark> por silencio administrativo, <mark class=\"m-personalizado\"><u class=\"m-clave\">excepto</u></mark> en los supuestos en los que una <mark class=\"m-destacable\">norma</mark> <mark class=\"m-personalizado\">con rango</mark> <mark class=\"m-destacable\">de</mark> ley o una norma <mark class=\"m-personalizado\">de</mark> <mark class=\"m-destacable\">Derecho</mark> de la <mark class=\"m-personalizado\"><u class=\"m-clave\">Unión</u> Europea</mark> <mark class=\"m-destacable\">o</mark> de Derecho <mark class=\"m-personalizado\"><u class=\"m-clave\">internacional</u></mark> <span class=\"m-caja\"><mark class=\"m-autoridad\">aplicable</mark></span> <mark class=\"m-autoridad\">en</mark> <mark class=\"m-personalizado\">España establezcan lo contrario</mark>. <mark class=\"m-personalizado\">Cuando</mark> el procedimiento tenga <mark class=\"m-personalizado\">por objeto el <u class=\"m-clave\">acceso a actividades</u> o su ejercicio</mark>, <mark class=\"m-personalizado\">la ley que</mark> disponga el carácter <mark class=\"m-personalizado\">desestimatorio</mark> del silencio <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">fundarse en la concurrencia de</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">razones</u></mark> <mark class=\"m-personalizado\">imperiosas de interés general</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1472\">🎯 1 pregunta</mark></p><p><span class=\"ex-plg\"><span class=\"ex-plg-t\">El silencio <mark class=\"m-accion\">tendrá</mark> efecto <mark class=\"m-destacable\">desestimatorio</mark> en los procedimientos relativos al ejercicio del <mark class=\"m-destacable\">derecho de petición</mark>, a que se refiere el <mark class=\"m-personalizado\">artículo 29 de la Constitución</mark>, aquellos cuya estimación tuviera como <mark class=\"m-personalizado\">consecuencia que se transfirieran al solicitante o a terceros facultades relativas</mark> al <mark class=\"m-destacable\"><u class=\"m-clave\">dominio público o</u> al servicio</mark> público, impliquen el ejercicio de <mark class=\"m-personalizado\">actividades</mark> que puedan <mark class=\"m-destacable\"><u class=\"m-clave\">dañar el</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">medio</u></mark> ambiente y en los procedimientos de <mark class=\"m-personalizado\"><u class=\"m-clave\">responsabilidad</u> patrimonial</mark> de las <mark class=\"m-autoridad\">Administraciones</mark> Públicas.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1473\">🎯 1 pregunta</mark></p><p>El sentido del silencio <mark class=\"m-personalizado\">también</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-destacable\">desestimatorio</mark> en los procedimientos de <mark class=\"m-destacable\">impugnación <u class=\"m-clave\">de</u> actos</mark> <mark class=\"m-personalizado\">y</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">disposiciones y</u></mark> <mark class=\"m-personalizado\">en los de</mark> <mark class=\"m-destacable\">revisión</mark> <mark class=\"m-personalizado\">de oficio iniciados a</mark> solicitud de los interesados. <mark class=\"m-personalizado\">No obstante</mark>, <mark class=\"m-personalizado\">cuando el</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">recurso de</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">alzada</u></mark> se haya interpuesto <mark class=\"m-personalizado\">contra la desestimación por silencio administrativo</mark> de una solicitud por el transcurso del plazo, <mark class=\"m-accion\">se entenderá</mark> <mark class=\"m-destacable\">estimado</mark> el mismo si, <mark class=\"m-personalizado\">llegado el plazo de resolución</mark>, el <mark class=\"m-autoridad\">órgano administrativo</mark> competente no <mark class=\"m-personalizado\">dictase y notificase resolución expresa</mark>, <mark class=\"m-personalizado\">siempre <u class=\"m-clave\">que</u> no se</mark> refiera a las materias enumeradas en el <mark class=\"m-personalizado\">párrafo anterior</mark> de este apartado. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1474\">🎯 1 pregunta</mark></p><p><b>a)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">En los <mark class=\"m-personalizado\">casos de</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">estimación por</u></mark> <mark class=\"m-personalizado\">silencio administrativo</mark>, la resolución expresa posterior a la producción del acto <mark class=\"m-personalizado\">sólo</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">dictarse de ser confirmatoria</mark> del mismo.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1476\">🎯 1 pregunta</mark></p><p><b>b)</b> En los casos de <mark class=\"m-personalizado\"><u class=\"m-clave\">desestimación</u> por silencio</mark> administrativo, <mark class=\"m-personalizado\">la resolución expresa posterior</mark> al vencimiento del plazo <mark class=\"m-accion\">se adoptará</mark> por la Administración <mark class=\"m-personalizado\"><u class=\"m-clave\">sin</u> vinculación alguna al sentido <u class=\"m-clave\">del</u> silencio</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1477\">🎯 1 pregunta</mark></p><p><b>4.</b> <mark class=\"m-personalizado\">Los actos administrativos</mark> producidos <mark class=\"m-personalizado\">por silencio</mark> administrativo <mark class=\"m-personalizado\"><u class=\"m-clave\">se</u></mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">hacer valer tanto ante</mark> <mark class=\"m-autoridad\">la Administración</mark> <mark class=\"m-personalizado\">como ante cualquier</mark> <mark class=\"m-autoridad\">persona física o jurídica</mark>, <mark class=\"m-autoridad\">pública o privada</mark>. Los mismos <mark class=\"m-personalizado\">producen efectos desde el vencimiento del plazo máximo</mark> en el que debe dictarse y notificarse la resolución expresa sin que la misma se haya expedido, <mark class=\"m-personalizado\">y su existencia puede ser acreditada por cualquier medio</mark> de prueba <mark class=\"m-personalizado\">admitido en Derecho</mark>, <mark class=\"m-personalizado\">incluido el</mark> <mark class=\"m-destacable\">certificado acreditativo del silencio</mark> producido. Este <mark class=\"m-destacable\">certificado</mark> <mark class=\"m-personalizado\">se</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">expedirá</mark> <mark class=\"m-personalizado\">de <u class=\"m-clave\">oficio</u></mark> por el <mark class=\"m-autoridad\">órgano competente</mark> para resolver</span></span> en el <mark class=\"m-resp r-ia\" data-q=\"11-ia-1478\">plazo de quince días desde que expire el plazo máximo para resolver el procedimiento</mark>. Sin perjuicio de lo anterior, <mark class=\"m-autoridad\">el interesado</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">pedirlo en cualquier momento</mark>, <mark class=\"m-personalizado\">computándose el plazo indicado anteriormente</mark> <mark class=\"m-plazo\">desde el día siguiente a aquél en que la petición tuviese entrada en el registro</mark> electrónico de la <mark class=\"m-autoridad\">Administración u Organismo</mark> competente para resolver. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1479\">🎯 1 pregunta</mark></p>"],["Artículo 25 — Falta de resolución expresa en procedimientos iniciados de oficio <span class=\"ex-sello ex-sello-r\">R21</span>","<p><b>a)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">En el caso de <mark class=\"m-personalizado\">procedimientos de los que pudiera derivarse</mark> <mark class=\"m-destacable\">el reconocimiento</mark> o, en su caso, la <mark class=\"m-personalizado\">constitución de</mark> <mark class=\"m-destacable\">derechos u</mark> <mark class=\"m-personalizado\">otras situaciones jurídicas</mark> <mark class=\"m-destacable\">favorables</mark>, <mark class=\"m-autoridad\">los interesados</mark> que hubieren comparecido <mark class=\"m-accion\">podrán entender</mark> desestimadas sus pretensiones <mark class=\"m-personalizado\">por silencio administrativo</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1480\">🎯 1 pregunta</mark></p><p><b>b)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">En <mark class=\"m-personalizado\">los procedimientos en</mark> que la <mark class=\"m-autoridad\">Administración</mark> ejercite <mark class=\"m-personalizado\">potestades</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">sancionadoras</u></mark> o, en <mark class=\"m-personalizado\">general</mark>, <mark class=\"m-personalizado\">de intervención</mark>, susceptibles de <span class=\"m-caja\">producir</span> <mark class=\"m-personalizado\">efectos</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">desfavorables o</u> de <u class=\"m-clave\">gravamen</u></mark>, <mark class=\"m-accion\">se producirá</mark> la <mark class=\"m-destacable\">caducidad</mark>. En estos casos, <mark class=\"m-personalizado\">la</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1481\">resolución que declare la caducidad ordenará el archivo de las actuaciones</mark>, con los efectos previstos en el artículo 95.</span></span></p>"],["Artículo 36 — Forma","<p><b>1.</b> <mark class=\"m-personalizado\">Los actos administrativos se</mark> <mark class=\"m-accion\">producirán</mark> <mark class=\"m-personalizado\">por</mark> <mark class=\"m-resp\" data-q=\"11-47\">escrito a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada de expresión y constancia</mark>.</p><p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">En los casos</mark> en que los <mark class=\"m-autoridad\">órganos</mark> administrativos <mark class=\"m-personalizado\">ejerzan su competencia de</mark> <mark class=\"m-destacable\">forma verbal</mark>, <mark class=\"m-personalizado\">la constancia escrita</mark> del acto, cuando sea necesaria, <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">efectuará</mark> <mark class=\"m-personalizado\">y</mark> <mark class=\"m-accion\">firmará</mark> <mark class=\"m-personalizado\">por</mark> <mark class=\"m-autoridad\">el titular del órgano inferior o funcionario</mark> <mark class=\"m-personalizado\">que la reciba oralmente</mark>, <mark class=\"m-personalizado\">expresando</mark> en la comunicación del mismo <mark class=\"m-personalizado\">la</mark> <mark class=\"m-autoridad\">autoridad</mark> de <mark class=\"m-personalizado\">la que procede</mark>. Si se tratara de resoluciones, <mark class=\"m-autoridad\">el titular</mark> de la <mark class=\"m-personalizado\">competencia</mark> <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">autorizar una relación de las que haya dictado de forma verbal</mark>, <mark class=\"m-personalizado\">con expresión de su contenido</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1506\">🎯 1 pregunta</mark></p><p><b>3.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Cuando deba dictarse una <mark class=\"m-destacable\">serie de actos administrativos</mark> <mark class=\"m-personalizado\">de la misma naturaleza</mark>, tales como <mark class=\"m-personalizado\">nombramientos</mark>, <mark class=\"m-personalizado\">concesiones o licencias</mark>, <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">refundirse en <u class=\"m-clave\">un único</u> acto</mark>, acordado por el <mark class=\"m-autoridad\">órgano</mark> competente, que <mark class=\"m-accion\">especificará</mark> las personas u otras circunstancias que individualicen los efectos del acto para cada interesado.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1507\">🎯 1 pregunta</mark></p>"],["Artículo 54 — Clases de iniciación <span class=\"ex-sello ex-sello-r\">R25</span>","<p data-r=\"R25\"><span class=\"ex-sello ex-sello-r\">R25</span> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Los procedimientos <mark class=\"m-accion\">podrán iniciarse</mark> <mark class=\"m-personalizado\">de</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-2115\">oficio o a solicitud del interesado</mark>.</span></span></p>"],["Artículo 56 — Medidas provisionales","<p><b>2.</b> <mark class=\"m-personalizado\">Antes <u class=\"m-clave\">de la iniciación</u> del procedimiento</mark> administrativo, el <mark class=\"m-autoridad\">órgano competente</mark> para <mark class=\"m-accion\">iniciar</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">o</mark></span> <span class=\"m-circulo\"><mark class=\"m-destacable\">instruir</mark></span> el <mark class=\"m-personalizado\">procedimiento</mark>, de <mark class=\"m-personalizado\">oficio</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">o</mark></span> <mark class=\"m-personalizado\">a instancia de parte</mark>, en los casos de urgencia <mark class=\"m-personalizado\">inaplazable y para</mark> la protección provisional de los <mark class=\"m-personalizado\">intereses implicados</mark>, <mark class=\"m-accion\">podrá adoptar</mark> de forma motivada las medidas provisionales que resulten <mark class=\"m-personalizado\">necesarias y proporcionadas</mark>. <mark class=\"m-personalizado\">Las medidas provisionales</mark> <mark class=\"m-accion\">deberán</mark> ser <mark class=\"m-autoridad\">confirmadas</mark>, <mark class=\"m-autoridad\">modificadas o</mark> levantadas <mark class=\"m-personalizado\">en</mark> el <mark class=\"m-autoridad\">acuerdo de iniciación</mark> del procedimiento, que <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">efectuarse dentro de</mark> los quince días <mark class=\"m-plazo\">siguientes a su adopción</mark>, el cual <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ser objeto del recurso que proceda</mark>. <mark class=\"m-resp ex-q\" data-q=\"11-193\">🎯 1 pregunta</mark></p><p><span class=\"ex-plg\"><span class=\"ex-plg-t\">(…) <b>4.</b> No <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">adoptar</mark> <mark class=\"m-destacable\">medidas provisionales</mark> que <mark class=\"m-resp r-ia\" data-q=\"11-ia-1548,11-ia-1555,11-ia-1650\">puedan causar perjuicio de difícil o imposible reparación a los interesados o que impliquen violación de derechos amparados por las leyes</mark>. (…)</span></span></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 57 — Acumulación <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><mark class=\"m-personalizado\">Contra el</mark> <mark class=\"m-destacable\">acuerdo de acumulación</mark> <mark class=\"m-accion\">no procederá</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1549\">recurso alguno</mark>.</p>"],["Artículo 61 — Inicio del procedimiento por petición razonada de otros órganos","<p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">La petición no vincula</mark> al <mark class=\"m-autoridad\">órgano</mark> competente <mark class=\"m-personalizado\">para iniciar</mark> el procedimiento, <mark class=\"m-personalizado\">si</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1551\">bien deberá comunicar al órgano que la hubiera formulado los motivos por los que, en su caso, no procede la iniciación</mark>.</span></span></p><p><b>4.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">En los procedimientos de <mark class=\"m-personalizado\">responsabilidad patrimonial</mark>, <mark class=\"m-destacable\">la petición</mark> <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">individualizar la lesión producida</mark> en una persona o grupo de personas, su <mark class=\"m-personalizado\">relación de <u class=\"m-clave\">causalidad</u></mark> con el funcionamiento del servicio público, <mark class=\"m-personalizado\">su evaluación económica si fuera posible</mark>, y <mark class=\"m-personalizado\">el <u class=\"m-clave\">momento</u></mark> en que la lesión efectivamente <mark class=\"m-personalizado\">se produjo</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1552\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 62 — Inicio del procedimiento por denuncia <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b>1.</b> Se entiende por <mark class=\"m-resp\" data-q=\"11-125\">denuncia</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">el acto por el que <mark class=\"m-personalizado\">cualquier persona</mark>, en cumplimiento o no de una obligación legal, <mark class=\"m-personalizado\">pone en conocimiento</mark> de un <mark class=\"m-autoridad\">órgano</mark> administrativo la existencia de un determinado <mark class=\"m-personalizado\">hecho que pudiera justificar la iniciación de oficio</mark> de un procedimiento administrativo.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1553\">🎯 1 pregunta</mark></p><p>(…) <b>5.</b> La presentación de una <mark class=\"m-personalizado\">denuncia no</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1556\">confiere, por sí sola, la condición de interesado en el procedimiento</mark>.</p>"],["Artículo 63 — Especialidades en el inicio de los procedimientos de naturaleza sancionadora","<p><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Los procedimientos de naturaleza sancionadora <mark class=\"m-personalizado\">se</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1557\">iniciarán siempre de oficio por acuerdo del órgano competente y establecerán la debida separación entre la fase instructora y la sancionadora, que se encomendará a órganos</mark> distintos.</span></span></p><p><b>3.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">No se</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">iniciar nuevos procedimientos de carácter sancionador por hechos o <u class=\"m-clave\">conductas</u> tipificadas como infracciones en cuya</mark> <mark class=\"m-autoridad\">comisión</mark> el <mark class=\"m-personalizado\">infractor <u class=\"m-clave\">persista</u></mark> de forma continuada, en <mark class=\"m-personalizado\">tanto</mark> no haya recaído una <mark class=\"m-personalizado\">primera resolución sancionadora</mark>, <mark class=\"m-personalizado\">con carácter</mark> ejecutivo.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1558\">🎯 1 pregunta</mark></p>"],["Artículo 64 — Acuerdo de iniciación en los procedimientos de naturaleza sancionadora","<p><b><mark class=\"m-personalizado\">a)</mark></b> <mark class=\"m-personalizado\">Identificación</mark> de la persona o personas presuntamente <mark class=\"m-personalizado\">responsables</mark>. b) <mark class=\"m-personalizado\">Los hechos</mark> que motivan la incoación del procedimiento, su posible <mark class=\"m-personalizado\">calificación y las sanciones</mark> que pudieran corresponder, sin perjuicio de lo que resulte de la instrucción. c) Identificación del <mark class=\"m-personalizado\">instructor y, en su caso</mark>, <mark class=\"m-autoridad\">Secretario</mark> del procedimiento, con expresa <mark class=\"m-personalizado\">indicación del régimen de recusación</mark> de los mismos. d) <mark class=\"m-autoridad\">Órgano</mark> <mark class=\"m-personalizado\">competente para la resolución</mark> del procedimiento <mark class=\"m-personalizado\">y norma</mark> que le atribuya tal competencia, indicando la <mark class=\"m-personalizado\">posibilidad</mark> de que el presunto responsable pueda <mark class=\"m-personalizado\">reconocer voluntariamente su responsabilidad</mark>, con los efectos previstos en el <mark class=\"m-personalizado\">artículo 85.</mark> e) <mark class=\"m-personalizado\">Medidas</mark> <mark class=\"m-autoridad\">de carácter provisional que se hayan acordado por el órgano</mark> competente para iniciar el procedimiento sancionador, <mark class=\"m-personalizado\">sin perjuicio de las que se puedan adoptar</mark> durante el mismo de conformidad con el artículo 56. f) <mark class=\"m-personalizado\">Indicación del derecho a formular alegaciones y a la</mark> <mark class=\"m-autoridad\">audiencia</mark> en el procedimiento <span class=\"m-circulo\"><mark class=\"m-personalizado\">y</mark></span> de los <mark class=\"m-personalizado\">plazos</mark> para su ejercicio, así como <mark class=\"m-personalizado\">indicación</mark> de que, en caso de <mark class=\"m-personalizado\">no efectuar alegaciones en el</mark> plazo previsto sobre el contenido del <mark class=\"m-personalizado\">acuerdo de iniciación</mark>, <mark class=\"m-personalizado\">éste</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ser</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1208,11-ia-1561\">considerado propuesta de resolución cuando contenga un pronunciamiento preciso acerca de la responsabilidad imputada</mark>. (…) <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1560\">🎯 1 pregunta</mark></p>"],["Artículo 65 — Especialidades en el inicio de oficio de los procedimientos de responsabilidad patrimonial","<p><b>2.</b> <mark class=\"m-personalizado\">El acuerdo de iniciación</mark> del procedimiento <mark class=\"m-accion\">se notificará</mark> a <mark class=\"m-autoridad\">los particulares</mark> <mark class=\"m-personalizado\">presuntamente lesionados</mark>, <mark class=\"m-personalizado\">concediéndoles</mark> un plazo de <mark class=\"m-resp r-ia\" data-q=\"11-ia-1563\">diez días</mark> para que <mark class=\"m-personalizado\">aporten</mark> cuantas <mark class=\"m-personalizado\"><u class=\"m-clave\">alegaciones</u></mark>, <mark class=\"m-personalizado\">documentos o información</mark> estimen conveniente a su <mark class=\"m-personalizado\">derecho y propongan</mark> cuantas <mark class=\"m-personalizado\">pruebas</mark> sean pertinentes para el reconocimiento del mismo. El procedimiento iniciado <mark class=\"m-destacable\">se</mark> <mark class=\"m-accion\">instruirá</mark> <mark class=\"m-destacable\">aunque</mark> los particulares presuntamente <mark class=\"m-destacable\">lesionados no se personen en el plazo</mark> establecido.</p>"],["Artículo 67 — Solicitudes de iniciación en los procedimientos de responsabilidad patrimonial","<p><b>1.</b> <mark class=\"m-autoridad\">Los interesados sólo</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">solicitar el inicio</mark> de un procedimiento de responsabilidad patrimonial, <mark class=\"m-personalizado\">cuando no haya <u class=\"m-clave\">prescrito</u> su derecho a reclamar</mark>. <mark class=\"m-destacable\">El derecho a reclamar</mark> <mark class=\"m-accion\">prescribirá</mark> al año de <mark class=\"m-resp r-ia\" data-q=\"11-ia-1568,11-ia-1638\">producido el hecho o el acto que motive la indemnización o se manifieste su efecto lesivo</mark>. <mark class=\"m-personalizado\">En caso de daños de carácter físico o psíquico a las personas</mark>, <mark class=\"m-personalizado\">el plazo</mark> <mark class=\"m-accion\">empezará</mark> <span class=\"m-caja\">a computarse</span> <mark class=\"m-personalizado\">desde</mark> la curación o <mark class=\"m-personalizado\">la determinación del alcance de las secuelas</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1569\">🎯 1 pregunta</mark></p><p><span class=\"ex-plg\"><span class=\"ex-plg-t\">En los casos en que proceda reconocer <mark class=\"m-destacable\">derecho a indemnización</mark> <mark class=\"m-personalizado\">por anulación en vía administrativa o contencioso-administrativa de un acto o disposición de <u class=\"m-clave\">carácter</u> general</mark>, el derecho a reclamar <mark class=\"m-accion\">prescribirá</mark> <mark class=\"m-plazo\">al año de haberse notificado la resolución</mark> administrativa <mark class=\"m-autoridad\">o</mark> <mark class=\"m-plazo\">la sentencia definitiva</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1570\">🎯 1 pregunta</mark></p>"],["Artículo 68 — Subsanación y mejora de la solicitud","<p><b>2.</b> <mark class=\"m-personalizado\">Siempre <u class=\"m-clave\">que no</u> se trate de procedimientos</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">selectivos o</u></mark> <mark class=\"m-personalizado\">de concurrencia</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">competitiva</u></mark>, este plazo <mark class=\"m-accion\">podrá</mark> ser ampliado prudencialmente, hasta <mark class=\"m-resp r-ia\" data-q=\"11-ia-1572,11-ia-1632\">cinco días</mark>, a petición del interesado o a iniciativa del <mark class=\"m-autoridad\">órgano,</mark> cuando la aportación de los documentos requeridos presente dificultades especiales.</p><p><b>4.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Si alguno de los sujetos a los que hace referencia el artículo 14.2 y 14.3 <mark class=\"m-personalizado\">presenta su solicitud presencialmente</mark>, las Administraciones Públicas <mark class=\"m-accion\">requerirán</mark> al interesado para que la <mark class=\"m-personalizado\">subsane a través de su presentación electrónica</mark>. A estos efectos, <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">considerará</mark> como <mark class=\"m-personalizado\">fecha de presentación</mark> de la solicitud aquella en la que haya sido <mark class=\"m-personalizado\">realizada la subsanación</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1573\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 69 — Declaración responsable y comunicación <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b>1.</b> A los efectos de esta Ley, <mark class=\"m-accion\">se entenderá</mark> por <mark class=\"m-resp\" data-q=\"11-159\">declaración responsable</mark> el <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">documento</mark> suscrito <mark class=\"m-autoridad\">por un interesado</mark> en el que éste <mark class=\"m-personalizado\">manifiesta</mark>, <mark class=\"m-personalizado\">bajo su responsabilidad</mark>, <mark class=\"m-personalizado\">que <u class=\"m-clave\">cumple</u> con los</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">requisitos</u></mark> establecidos en <mark class=\"m-personalizado\">la normativa</mark> vigente <mark class=\"m-personalizado\">para obtener el reconocimiento de un</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">derecho o facultad</mark></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">o</u> para su <u class=\"m-clave\">ejercicio</u></mark>, <mark class=\"m-personalizado\">que dispone de la</mark> <mark class=\"m-destacable\">documentación</mark> que así lo acredita, que la <mark class=\"m-accion\">pondrá</mark> <mark class=\"m-autoridad\">a disposición de la Administración</mark> cuando le sea requerida, <mark class=\"m-personalizado\">y que se compromete a mantener el cumplimiento de las</mark> anteriores obligaciones <mark class=\"m-personalizado\">durante</mark> el período <mark class=\"m-personalizado\">de tiempo</mark> inherente a dicho <mark class=\"m-personalizado\">reconocimiento o ejercicio</mark></span></span> . <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1574\">🎯 1 pregunta</mark></p><p class=\"ex-mas\"><mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1577\">🎯 1 pregunta más de este artículo</mark></p>"],["Artículo 77 — Medios y período de prueba <span class=\"ex-sello ex-sello-r\">R27</span>","<p data-r=\"R27\"><span class=\"ex-sello ex-sello-r\">R27</span> (…) <b>2.</b> Cuando la <mark class=\"m-autoridad\">Administración</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">no tenga</u> por <u class=\"m-clave\">ciertos</u> los hechos alegados por los interesados o la naturaleza del procedimiento lo exija</mark>, <mark class=\"m-autoridad\">el instructor</mark> del mismo <mark class=\"m-accion\">acordará</mark> <mark class=\"m-plazo\">la apertura de</mark> <mark class=\"m-destacable\">un</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1078,11-ia-1587,11-ia-1588\">período de prueba por un plazo no superior a treinta días ni inferior a diez</mark>, <mark class=\"m-autoridad\">a fin</mark> <mark class=\"m-personalizado\">de que puedan practicarse</mark> cuantas <mark class=\"m-personalizado\">juzgue pertinentes</mark>. <mark class=\"m-personalizado\">Asimismo</mark>, <mark class=\"m-personalizado\">cuando lo considere necesario</mark>, <mark class=\"m-personalizado\">el</mark> <mark class=\"m-autoridad\">instructor</mark>, a petición <mark class=\"m-autoridad\">de</mark> los interesados, <mark class=\"m-accion\">podrá decidir</mark> <mark class=\"m-personalizado\">la apertura de un período extraordinario de</mark> prueba por un plazo no superior a <mark class=\"m-personalizado\">diez</mark> días. (…)</p>"],["Artículo 80 — Emisión de informes <span class=\"ex-sello ex-sello-r\">R28</span>","<p><b>2.</b> Los informes <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">emitidos</u></mark> a través de <mark class=\"m-personalizado\">medios electrónicos</mark> y de acuerdo con los requisitos que señala el artículo 26 en el <mark class=\"m-plazo\">plazo de</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1594\">diez días, salvo que una disposición o el cumplimiento del resto de los plazos del procedimiento permita o exija otro plazo mayor o menor</mark>.</p><p><b>3.</b> <mark class=\"m-personalizado\">De</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">no</mark></span> <mark class=\"m-personalizado\">emitirse</mark> el informe en el plazo señalado, y <span class=\"m-caja\">sin perjuicio</span> de la <mark class=\"m-personalizado\">responsabilidad en que incurra</mark> el responsable de <mark class=\"m-personalizado\">la demora</mark>, <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">proseguir las</mark> actuaciones salvo cuando se trate de un <mark class=\"m-destacable\"><u class=\"m-clave\">informe</u> preceptivo</mark>, en cuyo caso <mark class=\"m-accion\">se podrá</mark> <mark class=\"m-destacable\">suspender</mark> el transcurso del <mark class=\"m-personalizado\">plazo máximo legal</mark> para resolver el procedimiento en los términos establecidos en la letra d) del apartado 1 del artículo 22. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1595\">🎯 1 pregunta</mark></p>"],["Artículo 81 — Solicitud de informes y dictámenes en los procedimientos de responsabilidad patrimonial","<p>(…) <b>2.</b> <mark class=\"m-accion\">Cuando las indemnizaciones reclamadas sean</mark> de cuantía igual o superior a <mark class=\"m-resp r-ia\" data-q=\"11-ia-1596\">50.000 euros</mark> <mark class=\"m-destacable\">o</mark> a la que se establezca en la correspondiente <mark class=\"m-personalizado\">legislación autonómica</mark>, así como en aquellos casos que disponga la Ley Orgánica 3/1980, de 22 de abril, del <mark class=\"m-autoridad\">Consejo de Estado,</mark> <mark class=\"m-accion\">será preceptivo</mark> <mark class=\"m-personalizado\">solicitar dictamen del</mark> <mark class=\"m-autoridad\">Consejo de Estado</mark> <mark class=\"m-personalizado\">o, en su</mark> caso, del <mark class=\"m-autoridad\">órgano consultivo de la Comunidad Autónoma</mark>.</p>"],["Artículo 95 — Requisitos y efectos <span class=\"ex-sello ex-sello-r\">R30</span>","<p data-r=\"R30\"><span class=\"ex-sello ex-sello-r\">R30</span> <b>1.</b> En los procedimientos iniciados <mark class=\"m-personalizado\">a <u class=\"m-clave\">solicitud del</u> interesado</mark>, cuando se produzca su <mark class=\"m-personalizado\">paralización por causa imputable al mismo</mark>, <mark class=\"m-personalizado\">la Administración le</mark> <mark class=\"m-accion\">advertirá</mark> <mark class=\"m-personalizado\">que,</mark> <mark class=\"m-plazo\">transcurridos</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1626\">tres meses</mark>, <mark class=\"m-accion\">se producirá</mark> <mark class=\"m-personalizado\">la caducidad del procedimiento</mark>. <mark class=\"m-personalizado\">Consumido este plazo sin que el particular</mark> requerido realice las actividades necesarias para reanudar la tramitación, <mark class=\"m-personalizado\">la</mark> Administración <mark class=\"m-accion\">acordará</mark> <mark class=\"m-personalizado\">el archivo de</mark> las actuaciones, <mark class=\"m-personalizado\">notificándoselo al</mark> <mark class=\"m-autoridad\">interesado</mark>. <mark class=\"m-personalizado\">Contra la resolución</mark> que declare la caducidad <mark class=\"m-accion\">procederán</mark> <mark class=\"m-personalizado\">los recursos pertinentes</mark>. (…)</p>"],["Artículo 117 — Suspensión de la ejecución","<p><span class=\"ex-plg\"><span class=\"ex-plg-t\">(…) <b>3.</b> La ejecución del acto impugnado <mark class=\"m-accion\">se entenderá</mark> suspendida si transcurrido un <mark class=\"m-resp r-ia\" data-q=\"11-ia-1670\">mes</mark> desde que <mark class=\"m-destacable\">la solicitud</mark> de suspensión <mark class=\"m-personalizado\">haya</mark> <mark class=\"m-destacable\">tenido</mark> <mark class=\"m-personalizado\">entrada</mark> en el registro electrónico de <mark class=\"m-autoridad\">la Administración u Organismo competente</mark> para decidir sobre la misma, el <mark class=\"m-autoridad\">órgano</mark> a quien competa resolver el recurso <mark class=\"m-personalizado\">no ha <u class=\"m-clave\">dictado</u> y <u class=\"m-clave\">notificado resolución</u> expresa al respecto</mark>. En estos casos, <mark class=\"m-accion\">no será</mark> de aplicación lo establecido en el artículo 21.4 segundo párrafo, de esta Ley. (…)</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1668\">🎯 1 pregunta</mark></p><p class=\"ex-mas\"><mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1671,11-ia-1672\">🎯 2 preguntas más de este artículo</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 118 — Audiencia de los interesados <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"1\"><b>1.</b> Cuando hayan de tenerse en cuenta <mark class=\"m-personalizado\">nuevos hechos</mark> o documentos <mark class=\"m-personalizado\">no recogidos en el expediente</mark> <mark class=\"m-plazo\">originario, se</mark> <mark class=\"m-accion\">pondrán</mark> <mark class=\"m-plazo\">de manifiesto</mark> <mark class=\"m-personalizado\">a los interesados</mark> para <mark class=\"m-plazo\">que, en un plazo no inferior a diez</mark> <mark class=\"m-destacable\">días</mark> <mark class=\"m-plazo\">ni superior a quince,</mark> <mark class=\"m-resp\" data-q=\"11-185\">formulen las <mark class=\"m-destacable\">alegaciones</mark> y presenten los documentos y justificantes que estimen procedentes</mark>.</p><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">No se</mark> <mark class=\"m-accion\">tendrán</mark> <mark class=\"m-destacable\">en cuenta en la resolución de los recursos, hechos, documentos o alegaciones del</mark> recurrente, cuando habiendo <mark class=\"m-personalizado\">podido aportarlos</mark> <mark class=\"m-plazo\">en el</mark> <mark class=\"m-autoridad\">trámite de alegaciones</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">no</u> lo haya hecho. Tampoco</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">solicitarse</mark> la práctica <mark class=\"m-personalizado\">de pruebas</mark> cuando su <mark class=\"m-personalizado\">falta de realización</mark> en el procedimiento en el que se dictó la resolución recurrida fuera <mark class=\"m-personalizado\">imputable al interesado.</mark></span></span></p><p data-ex=\"1\"><b>2.</b> Si hubiera <mark class=\"m-personalizado\">otros interesados</mark> se les <mark class=\"m-accion\">dará,</mark> en todo caso, <mark class=\"m-personalizado\">traslado del recurso para que en el plazo</mark> antes citado, <mark class=\"m-personalizado\">aleguen</mark> cuanto estimen procedente.</p><p data-ex=\"1\"><b>3.</b> <mark class=\"m-personalizado\">El <mark class=\"m-resp r-ia\" data-q=\"11-ia-1674\">recurso, los informes y las propuestas</mark> no</mark> tienen <span class=\"ex-plg\"><span class=\"ex-plg-t\">el carácter de <mark class=\"m-personalizado\">documentos nuevos</mark> a los efectos de este artículo. <mark class=\"m-personalizado\">Tampoco lo</mark> <mark class=\"m-accion\">tendrán</mark> los que los interesados hayan <mark class=\"m-personalizado\">aportado</mark> al expediente <mark class=\"m-personalizado\">antes de recaer la resolución</mark> impugnada.</span></span></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 119 — Resolución <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"1\"><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">La resolución del recurso <mark class=\"m-accion\">estimará</mark> en todo o en parte o <mark class=\"m-accion\">desestimará</mark> las pretensiones formuladas en el mismo o <mark class=\"m-accion\">declarará</mark> su inadmisión.</span></span></p><p data-ex=\"1\"><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Cuando existiendo vicio de forma no se estime procedente resolver sobre el fondo <mark class=\"m-accion\">se ordenará</mark> la retroacción del procedimiento al momento en el que el vicio fue cometido, sin perjuicio de que eventualmente pueda acordarse la convalidación de actuaciones por el <mark class=\"m-autoridad\">órgano</mark> competente para ello, de acuerdo con lo dispuesto en el artículo 52.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1675\">🎯 1 pregunta</mark></p><p data-ex=\"1\"><b>3.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">El <mark class=\"m-autoridad\">órgano</mark> que resuelva el recurso <mark class=\"m-accion\">decidirá</mark> cuantas cuestiones, tanto de forma como de fondo, plantee el procedimiento, hayan sido o no alegadas por los interesados. En este último caso se les <mark class=\"m-accion\">oirá</mark> previamente.</span></span> No obstante, la <span class=\"ex-plg\"><span class=\"ex-plg-t\">resolución <mark class=\"m-accion\">será</mark> congruente con las peticiones formuladas por el recurrente, sin que en ningún</span></span> caso pueda <mark class=\"m-resp\" data-q=\"11-186\">agravarse su situación inicial</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1614,11-ia-1676\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 120 — Pluralidad de recursos administrativos <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b>1.</b> Cuando deban resolverse una <mark class=\"m-personalizado\">pluralidad</mark> <mark class=\"m-destacable\">de recursos</mark> administrativos <mark class=\"m-personalizado\">que traigan causa de un mismo acto administrativo <u class=\"m-clave\">y</u></mark> se hubiera <mark class=\"m-personalizado\">interpuesto un recurso judicial contra una resolución</mark> administrativa <mark class=\"m-personalizado\">o</mark> bien contra el correspondiente <mark class=\"m-personalizado\">acto presunto desestimatorio</mark>, el <mark class=\"m-autoridad\">órgano administrativo</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">acordar la <u class=\"m-clave\">suspensión</u> del plazo para resolver hasta que recaiga pronunciamiento judicial</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1395\">🎯 1 pregunta</mark></p><p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">El acuerdo de suspensión</mark> <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">ser notificado</mark> a los interesados, quienes <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">recurrirlo</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1677\">🎯 1 pregunta</mark></p><p><b>3.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\"><u class=\"m-clave\">Recaído el</u> pronunciamiento judicial</mark>, <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">comunicado a</mark> los <mark class=\"m-autoridad\">interesados y el órgano administrativo</mark> competente para resolver <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">dictar resolución sin necesidad</mark> de realizar <span class=\"m-caja\">ningún trámite adicional</span>, <mark class=\"m-personalizado\"><u class=\"m-clave\">salvo</u> el de</mark> <mark class=\"m-autoridad\">audiencia,</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">cuando proceda</u></mark>.</span></span> <mark class=\"m-resp ex-q\" data-q=\"11-58\">🎯 1 pregunta</mark></p>"],["Artículo 125 — Objeto y plazos","<p>(…) <b>2.</b> El <span class=\"ex-plg\"><span class=\"ex-plg-t\">recurso extraordinario de revisión <mark class=\"m-accion\">se interpondrá,</mark> cuando se trate de la causa a) del apartado anterior, dentro del</span></span> plazo de <mark class=\"m-resp\" data-q=\"11-99,11-113,11-ia-1689,11-ia-1690,11-ia-1712,11-ia-1881\">cuatro años siguientes a la fecha de la notificación de la resolución impugnada. En los demás casos, el plazo será de tres meses a contar</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-plazo\">desde el conocimiento de</mark> los documentos o desde <mark class=\"m-plazo\">que la sentencia judicial quedó firme</mark></span></span> . (…)</p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 126 — Resolución <span class=\"ex-sello\">EX</span> <span class=\"ex-sello ex-sello-r\">R34</span></div><div class=\"ex-fb\"><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\"><b><mark class=\"m-personalizado\">1.</mark></b> <mark class=\"m-personalizado\">El</mark> <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-personalizado\">competente para la resolución</mark> <mark class=\"m-destacable\">del</mark> recurso <mark class=\"m-accion\">podrá acordar</mark> motivadamente <mark class=\"m-personalizado\">la</mark> inadmisión <mark class=\"m-destacable\">a</mark> trámite, sin necesidad <mark class=\"m-personalizado\">de</mark> recabar dictamen del <mark class=\"m-autoridad\">Consejo de <u class=\"m-clave\">Estado</u> u órgano</mark></span></span></p><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\">consultivo <mark class=\"m-personalizado\">de la</mark> <mark class=\"m-plazo\">Comunidad Autónoma,</mark> cuando el mismo no se funde en alguna de las causas previstas en el apartado 1 del artículo <mark class=\"m-personalizado\">anterior o</mark> <mark class=\"m-destacable\">en</mark> <mark class=\"m-personalizado\">el supuesto</mark> de que se hubiesen <mark class=\"m-personalizado\">desestimado en</mark> cuanto al fondo <mark class=\"m-personalizado\">otros recursos sustancialmente iguales.</mark></span></span></p><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\"><b><mark class=\"m-destacable\">2.</mark></b> <mark class=\"m-destacable\">El</mark> <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-destacable\">al que corresponde conocer</mark> del recurso extraordinario de revisión <mark class=\"m-destacable\">debe pronunciarse no sólo sobre</mark> la <mark class=\"m-destacable\">procedencia del recurso, sino también, en su</mark> caso, <mark class=\"m-personalizado\">sobre el</mark> <mark class=\"m-destacable\">fondo</mark> de <mark class=\"m-personalizado\">la cuestión resuelta por</mark> el acto recurrido.</span></span></p><p data-ex=\"1\" data-r=\"R34\"><span class=\"ex-sello ex-sello-r\">R34</span> <b>3.</b> <mark class=\"m-personalizado\">Transcurrido</mark> el <mark class=\"m-autoridad\">plazo de tres meses</mark> desde la interposición del recurso extraordinario <mark class=\"m-personalizado\">de</mark> revisión <mark class=\"m-personalizado\">sin haberse dictado y notificado la resolución,</mark> <mark class=\"m-accion\">se entenderá</mark> <mark class=\"m-destacable\">desestimado,</mark> <mark class=\"m-personalizado\">quedando expedita</mark> la vía <mark class=\"m-personalizado\">jurisdiccional contencioso-administrativa.</mark></p>"],["Artículo 128 — Potestad reglamentaria","<p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">Los reglamentos y disposiciones administrativas</mark> <mark class=\"m-accion\">no podrán</mark> <mark class=\"m-personalizado\">vulnerar la Constitución <u class=\"m-clave\">o</u> las leyes <u class=\"m-clave\">ni</u> regular</mark> aquellas <mark class=\"m-personalizado\">materias que la Constitución o los Estatutos</mark> de Autonomía <mark class=\"m-personalizado\">reconocen</mark> de la competencia de las <mark class=\"m-autoridad\">Cortes Generales</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">o</mark></span> de las <mark class=\"m-autoridad\">Asambleas Legislativas</mark> de las Comunidades Autónomas. <mark class=\"m-personalizado\"><u class=\"m-clave\">Sin perjuicio</u> de su <u class=\"m-clave\">función</u> de desarrollo o colaboración</mark> con respecto a la <mark class=\"m-personalizado\">ley</mark>, <mark class=\"m-personalizado\">no</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1045,11-ia-1692\">tipificar delitos, faltas o infracciones administrativas, establecer penas o sanciones, así como tributos, exacciones parafiscales u otras cargas o prestaciones personales o patrimoniales de carácter público</mark>.</span></span></p><p class=\"ex-mas\"><mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1693\">🎯 1 pregunta más de este artículo</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 129 — Principios de buena regulación <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p>(…) <b>6.</b> En aplicación del <mark class=\"m-resp\" data-q=\"11-130,11-ia-2009\">principio de eficiencia</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">la iniciativa normativa debe <mark class=\"m-personalizado\">evitar cargas administrativas innecesarias o accesorias y racionalizar</mark>, en su aplicación, la gestión de los <mark class=\"m-personalizado\">recursos públicos</mark></span></span> . (…)</p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 131 — Publicidad de las normas <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"1\"><mark class=\"m-personalizado\">Las normas con rango</mark> <mark class=\"m-destacable\">de ley,</mark> <mark class=\"m-personalizado\">los reglamentos y disposiciones administrativas</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">habrán de</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">publicarse</u> en el <mark class=\"m-resp r-ia\" data-q=\"11-ia-1697\">diario oficial correspondiente</mark> para que entren <u class=\"m-clave\">en vigor</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">y</mark></span> <mark class=\"m-personalizado\">produzcan efectos jurídicos. <u class=\"m-clave\">Adicionalmente,</u> y de manera facultativa, las</mark> <mark class=\"m-autoridad\">Administraciones Públicas</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">establecer otros medios</mark> de publicidad complementarios.</span></span></p><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\">La publicación de los diarios o boletines oficiales en las sedes electrónicas de la Administración, <mark class=\"m-autoridad\">Órgano,</mark> Organismo público o Entidad competente <mark class=\"m-accion\">tendrá,</mark> en las condiciones y con las garantías que cada Administración Pública determine, los mismos efectos que los atribuidos a su edición impresa.</span></span></p><p data-ex=\"1\"><mark class=\"m-personalizado\">La publicación del «Boletín Oficial del</mark> <mark class=\"m-autoridad\">Estado»</mark> <mark class=\"m-personalizado\">en la sede</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">electrónica</mark> <mark class=\"m-personalizado\">del</mark> Organismo competente</span></span> <mark class=\"m-accion\">tendrá</mark> carácter <mark class=\"m-resp\" data-q=\"11-191\">oficial y auténtico en las condiciones y con las garantías que se determinen reglamentariamente</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">derivándose de dicha publicación los efectos previstos en el título preliminar del Código Civil y en las restantes normas aplicables.</span></span></p>"],["Artículo 12 — Delegación de firma","<p><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Los titulares de los <mark class=\"m-autoridad\">órganos</mark> administrativos <mark class=\"m-accion\">podrán,</mark> en materias de su <mark class=\"m-personalizado\">competencia</mark>, que <mark class=\"m-personalizado\">ostenten</mark>, <mark class=\"m-personalizado\">bien por atribución</mark>, <mark class=\"m-personalizado\">bien por delegación</mark> de competencias, delegar la firma de sus resoluciones y actos <mark class=\"m-destacable\">administrativos</mark> <mark class=\"m-personalizado\">en los titulares</mark> de los <mark class=\"m-autoridad\">órganos</mark> o unidades administrativas que de ellos <mark class=\"m-personalizado\">dependan</mark>, <mark class=\"m-personalizado\">dentro</mark> de los límites <mark class=\"m-personalizado\">señalados</mark> en el artículo 9.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1780\">🎯 1 pregunta</mark></p><p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">La <mark class=\"m-destacable\">delegación de firma</mark> no <mark class=\"m-resp r-ia\" data-q=\"11-ia-1779\">alterará la competencia del órgano delegante y para su validez no será necesaria</mark> su <mark class=\"m-destacable\">publicación</mark>.</span></span></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Suplencia (art. 13 · cuadro del temario)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Concepto</span><span>Contenido</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Concepto</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">En la forma que disponga cada Administración Pública, los titulares de los órganos administrativos podrán ser suplidos temporalmente.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">No implicará alteración de la competencia; para su validez no será <u class=\"m-clave\">necesaria</u> su publicación.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Si no se designa suplente, la competencia se ejercerá por quien designe el órgano administrativo inmediato superior de quien dependa.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Supuestos</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-plazo\">Vacante, ausencia, enfermedad</mark>, así como en los casos en que haya sido declarada su <mark class=\"m-plazo\">abstención o recusación</mark>.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Designación (en el ámbito de la AGE)</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">En los reales decretos de estructura orgánica básica de los Departamentos Ministeriales o en los estatutos de sus Organismos públicos y Entidades vinculados o dependientes.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Por el órgano competente para el nombramiento del titular, bien en el propio acto de nombramiento, bien en otro posterior cuando se produzca el supuesto que dé lugar a la suplencia.</div></div></div></div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 13 — <mark class=\"m-destacable\">Suplencia</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1782\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 14 — Decisiones sobre competencia","<p><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">El</mark> <mark class=\"m-autoridad\">órgano</mark> administrativo que se <mark class=\"m-personalizado\">estime incompetente</mark> para la resolución de un asunto <mark class=\"m-accion\">remitirá</mark> <mark class=\"m-personalizado\">directamente</mark> las actuaciones <mark class=\"m-personalizado\">al</mark> <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-personalizado\">que considere competente</mark>, <mark class=\"m-personalizado\">debiendo notificar esta</mark> circunstancia a los interesados.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1784\">🎯 1 pregunta</mark></p><p><b>3.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">Los conflictos</mark> de atribuciones sólo <mark class=\"m-accion\">podrán suscitarse</mark> entre <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-destacable\">de</mark> una <mark class=\"m-resp r-ia\" data-q=\"11-ia-1785\">misma Administración no relacionados jerárquicamente, y respecto a asuntos sobre los que no haya finalizado el procedimiento administrativo</mark>.</span></span></p>"],["Artículo 21 — Clasificación y composición de los órganos colegiados","<p><b>a)</b> <mark class=\"m-resp\" data-q=\"11-202\">Órganos colegiados interministeriales, si sus miembros proceden de diferentes Ministerios</mark>.</p><p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">En los <mark class=\"m-autoridad\">órganos</mark> colegiados a los que se refiere el <mark class=\"m-personalizado\">apartado anterior</mark>, <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">haber representantes de otras Administraciones</mark> Públicas, <mark class=\"m-personalizado\">cuando</mark> éstas lo <mark class=\"m-personalizado\">acepten voluntariamente</mark>, <mark class=\"m-personalizado\">cuando un convenio</mark> así lo establezca <span class=\"m-circulo\"><mark class=\"m-personalizado\">o</mark></span> cuando una <mark class=\"m-personalizado\">norma</mark> aplicable a las Administraciones afectadas <mark class=\"m-personalizado\">lo determine</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1808\">🎯 1 pregunta</mark></p>"],["Artículo 22 — Creación, modificación y supresión de órganos colegiados","<p><span class=\"ex-plg\"><span class=\"ex-plg-t\">(…) <b>2.</b> En los supuestos enunciados en el <mark class=\"m-personalizado\">apartado anterior</mark>, la <mark class=\"m-destacable\">norma de creación</mark> <mark class=\"m-accion\">deberá revestir</mark> la <mark class=\"m-destacable\">forma</mark> <mark class=\"m-personalizado\">de</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1810\">Real Decreto</mark> en el caso de los <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-personalizado\">colegiados interministeriales</mark> cuyo <mark class=\"m-autoridad\">Presidente</mark> tenga <mark class=\"m-personalizado\">rango superior al de Director general</mark>; <mark class=\"m-destacable\">Orden ministerial conjunta</mark> <mark class=\"m-personalizado\">para los restantes</mark> <mark class=\"m-autoridad\">órganos</mark> colegiados interministeriales, y <mark class=\"m-destacable\">Orden ministerial</mark> <mark class=\"m-personalizado\">para los de este carácter</mark>. (…)</span></span></p>"],["Artículo 25 — Principio de legalidad","<p><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\"><u class=\"m-clave\">La potestad</u> sancionadora de las</mark> <mark class=\"m-autoridad\">Administraciones Públicas</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">ejercerá</mark> <mark class=\"m-personalizado\">cuando haya sido <u class=\"m-clave\">expresamente</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">reconocida</mark></span> <mark class=\"m-personalizado\">por una</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1190,11-ia-1305,11-ia-1822,11-ia-2017\">norma con rango de Ley, con aplicación del procedimiento previsto</mark> para su ejercicio y de acuerdo con lo establecido en <mark class=\"m-destacable\">esta Ley y</mark> en <mark class=\"m-destacable\">la Ley de Procedimiento Administrativo</mark> Común de las Administraciones Públicas <span class=\"m-circulo\"><mark class=\"m-personalizado\">y,</mark></span> cuando se trate <mark class=\"m-personalizado\">de Entidades Locales</mark>, de conformidad con lo dispuesto en el Título XI de la <mark class=\"m-personalizado\">Ley 7/1985,</mark> de 2 de abril.</span></span></p><p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\"><u class=\"m-clave\">El ejercicio</u></mark> de la potestad sancionadora <mark class=\"m-personalizado\">corresponde a los</mark> <mark class=\"m-autoridad\">órganos</mark> administrativos que la tengan <mark class=\"m-personalizado\"><u class=\"m-clave\">expresamente atribuida</u></mark>, por disposición de <mark class=\"m-personalizado\">rango <mark class=\"m-resp r-ia\" data-q=\"11-ia-1823\">legal o reglamentario</mark></mark>.</span></span></p>"],["Artículo 26 — Irretroactividad","<p><b>2.</b> Las disposiciones sancionadoras <mark class=\"m-resp r-ia\" data-q=\"11-ia-1037,11-ia-1825\">producirán efecto retroactivo en cuanto favorezcan al presunto infractor o al infractor, tanto en lo referido a la tipificación de la infracción como a la sanción y a sus plazos de prescripción</mark>, <mark class=\"m-personalizado\">incluso</mark> respecto de las sanciones pendientes de cumplimiento al entrar en vigor la nueva disposición.</p>"],["Artículo 27 — Principio de tipicidad","<p>Las infracciones administrativas <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">clasificarán</mark> por la Ley en <mark class=\"m-resp\" data-q=\"11-88\">leves, graves y muy</mark> <mark class=\"m-destacable\">graves</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">2. <mark class=\"m-personalizado\">Únicamente por la</mark> <mark class=\"m-autoridad\">comisión</mark> <mark class=\"m-personalizado\">de infracciones</mark> administrativas <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">imponerse sanciones que, en todo caso</u></mark>, <mark class=\"m-accion\">estarán</mark> <mark class=\"m-personalizado\">delimitadas por la Ley</mark>. 3. <mark class=\"m-personalizado\">Las disposiciones</mark> <mark class=\"m-destacable\">reglamentarias</mark> <mark class=\"m-personalizado\">de desarrollo</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">introducir especificaciones o graduaciones <u class=\"m-clave\">al</u> cuadro de las <u class=\"m-clave\">infracciones</u> o sanciones establecidas legalmente</mark> <mark class=\"m-destacable\">que,</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">sin</u> constituir nuevas</mark> infracciones o sanciones, ni <mark class=\"m-personalizado\">alterar la naturaleza o límites</mark> de las que la Ley contempla, <mark class=\"m-personalizado\">contribuyan a</mark> la más <mark class=\"m-personalizado\">correcta identificación</mark> de las conductas <span class=\"m-circulo\"><mark class=\"m-personalizado\">o</mark></span> a la más <mark class=\"m-personalizado\">precisa determinación de las sanciones correspondientes</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1826\">🎯 1 pregunta</mark></p>"],["Artículo 28 — Responsabilidad","<p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><b><mark class=\"m-destacable\">1.</mark></b> Sólo <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">ser sancionadas por</mark> hechos constitutivos de infracción administrativa las <mark class=\"m-personalizado\">personas</mark> físicas y jurídicas, así como, cuando una Ley <mark class=\"m-personalizado\">les reconozca <u class=\"m-clave\">capacidad de obrar</u></mark>, <mark class=\"m-personalizado\">los grupos de afectados</mark>, <mark class=\"m-personalizado\">las uniones y entidades sin personalidad jurídica y los patrimonios independientes o autónomos</mark>, que resulten responsables de los mismos a título de <mark class=\"m-resp r-ia\" data-q=\"11-ia-1827\">dolo o culpa</mark>. (…)</span></span></p>"],["Artículo 29 — Principio de proporcionalidad","<p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><b><mark class=\"m-personalizado\">1.</mark></b> <mark class=\"m-personalizado\">Las sanciones</mark> administrativas, sean o <mark class=\"m-personalizado\"><u class=\"m-clave\">no de</u></mark> naturaleza <mark class=\"m-personalizado\">pecuniaria</mark>, en <mark class=\"m-resp r-ia\" data-q=\"11-ia-1829\">ningún caso podrán implicar, directa o subsidiariamente, privación de libertad</mark>.</span></span></p><p><b>a)</b> <mark class=\"m-personalizado\">El <u class=\"m-clave\">grado</u> de culpabilidad</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">o</mark></span> la existencia de <mark class=\"m-personalizado\">intencionalidad</mark>. b) <mark class=\"m-personalizado\">La <u class=\"m-clave\">continuidad</u> o persistencia</mark> en la conducta infractora. c) La naturaleza de los <mark class=\"m-personalizado\"><u class=\"m-clave\">perjuicios</u> causados</mark>. d) <mark class=\"m-destacable\"><u class=\"m-clave\">La reincidencia</u></mark>, por <mark class=\"m-autoridad\">comisión</mark> en el término <mark class=\"m-plazo\">de</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">un año de más de una</u></mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1228,11-ia-1688\">infracción de la misma naturaleza cuando así haya sido declarado por resolución firme en vía administrativa</mark>. (…) <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1831\">🎯 1 pregunta</mark></p><p class=\"ex-mas\"><mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1834\">🎯 1 pregunta más de este artículo</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 30 — Prescripción <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><mark class=\"m-accion\">prescribirán</mark> <mark class=\"m-destacable\">a los</mark> <mark class=\"m-plazo\">tres años</mark> , las graves a los dos años y las leves a los <mark class=\"m-resp\" data-q=\"11-131,11-ia-1241,11-ia-1835,11-ia-1836,11-ia-1907\">seis meses; las sanciones impuestas por faltas muy graves prescribirán a los tres años, las impuestas por faltas graves a los dos años y las impuestas por faltas leves al año</mark>.</p><p><b>2.</b> El plazo de <mark class=\"m-personalizado\">prescripción</mark> de las <mark class=\"m-destacable\">infracciones</mark> <mark class=\"m-accion\">comenzará</mark> a contarse desde el día en que la infracción <mark class=\"m-autoridad\">se</mark> <mark class=\"m-plazo\">hubiera cometido</mark>. En el caso de infracciones <mark class=\"m-personalizado\">continuadas o permanentes</mark>, el plazo <mark class=\"m-accion\">comenzará</mark> a correr <mark class=\"m-plazo\">desde</mark> <span class=\"m-caja\"><mark class=\"m-plazo\">que</mark></span> <mark class=\"m-plazo\">finalizó la conducta infractora</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1837\">🎯 1 pregunta</mark></p><p><mark class=\"m-accion\">Interrumpirá</mark> la <mark class=\"m-destacable\">prescripción</mark> <mark class=\"m-personalizado\">la <u class=\"m-clave\">iniciación</u></mark>, <mark class=\"m-personalizado\">con conocimiento</mark> <mark class=\"m-autoridad\">del interesado</mark>, de un procedimiento administrativo de naturaleza <mark class=\"m-personalizado\">sancionadora</mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">reiniciándose</u></mark> el plazo de prescripción si el expediente sancionador estuviera <mark class=\"m-personalizado\"><u class=\"m-clave\">paralizado</u></mark> <mark class=\"m-autoridad\">durante</mark> <mark class=\"m-plazo\">más</mark> <mark class=\"m-autoridad\">de un</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1838\">mes por causa no imputable al presunto responsable</mark>. (…)</p>"],["Artículo 31 — Concurrencia de sanciones","<p><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">No</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">sancionarse</u> los hechos que lo <u class=\"m-clave\">hayan sido penal o</u> administrativamente</mark>, <mark class=\"m-personalizado\">en los casos</mark> en que se aprecie <mark class=\"m-resp r-ia\" data-q=\"11-ia-1840\">identidad del sujeto, hecho y fundamento</mark>.</span></span></p><p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Cuando</mark> un <mark class=\"m-autoridad\">órgano</mark> de la <mark class=\"m-autoridad\">Unión Europea</mark> hubiera <mark class=\"m-personalizado\">impuesto una sanción por los mismos hechos</mark>, <mark class=\"m-personalizado\">y</mark> siempre que <span class=\"m-circulo\"><mark class=\"m-personalizado\">no</mark></span> <mark class=\"m-personalizado\">concurra la identidad de sujeto y fundamento</mark>, el <mark class=\"m-autoridad\">órgano</mark> competente para resolver <mark class=\"m-accion\">deberá tenerla</mark> <mark class=\"m-personalizado\">en cuenta a</mark> efectos <mark class=\"m-personalizado\">de graduar</mark> la que, en su caso, deba imponer, <mark class=\"m-personalizado\">pudiendo minorarla</mark>, sin perjuicio de declarar la <mark class=\"m-autoridad\">comisión</mark> de la infracción.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1841\">🎯 1 pregunta</mark></p>"],["Artículo 33 — Responsabilidad concurrente de las Administraciones Públicas","<p><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Cuando de <mark class=\"m-personalizado\">la gestión</mark> dimanante <mark class=\"m-personalizado\">de fórmulas conjuntas</mark> de actuación entre <mark class=\"m-autoridad\">varias Administraciones</mark> públicas <mark class=\"m-personalizado\">se derive responsabilidad</mark> en los términos previstos <mark class=\"m-personalizado\">en la</mark> presente Ley, las Administraciones <mark class=\"m-personalizado\">intervinientes</mark> <mark class=\"m-accion\">responderán</mark> <mark class=\"m-personalizado\">frente</mark> <mark class=\"m-autoridad\">al particular</mark>, <mark class=\"m-destacable\"><u class=\"m-clave\">en</u></mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1371\">todo caso, de forma solidaria. El instrumento jurídico regulador de la actuación conjunta podrá determinar la distribución de la responsabilidad</mark> entre las diferentes Administraciones públicas.</span></span></p><p><b>4.</b> Cuando se trate de <mark class=\"m-personalizado\">procedimientos</mark> en materia de <mark class=\"m-personalizado\">responsabilidad patrimonial</mark>, <mark class=\"m-autoridad\">la Administración</mark> Pública <mark class=\"m-autoridad\">competente</mark> a la que se refiere el apartado anterior, <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">consultar a las restantes Administraciones implicadas para que,</mark> en <mark class=\"m-plazo\">el plazo de</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1478\">quince días, éstas puedan exponer cuanto consideren procedente</mark>.</p><p class=\"ex-mas\"><mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1845\">🎯 1 pregunta más de este artículo</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 34 — Indemnización <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"1\"><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">Sólo</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">indemnizables las lesiones</mark> producidas al <mark class=\"m-autoridad\">particular</mark> provenientes de <mark class=\"m-personalizado\">daños que éste <u class=\"m-clave\">no</u> tenga el deber jurídico de soportar</mark> de acuerdo con la <mark class=\"m-personalizado\">Ley.</mark> <mark class=\"m-accion\">No serán</mark> <mark class=\"m-destacable\">indemnizables</mark> los daños que se deriven de <mark class=\"m-personalizado\">hechos o</mark> circunstancias que <mark class=\"m-personalizado\"><u class=\"m-clave\">no</u> se hubiesen podido prever o evitar según</mark> el estado de los <mark class=\"m-personalizado\">conocimientos de la ciencia <u class=\"m-clave\">o</u> de la técnica</mark> existentes en el momento de producción de aquéllos, todo ello <mark class=\"m-personalizado\">sin perjuicio de las prestaciones asistenciales o económicas</mark> que las leyes puedan establecer para estos casos.</span></span> <mark class=\"m-resp ex-q\" data-q=\"11-194,11-ia-1846\">🎯 2 preguntas</mark></p><p data-ex=\"1\">En <mark class=\"m-personalizado\">los casos de responsabilidad</mark> <mark class=\"m-destacable\">patrimonial</mark> <mark class=\"m-personalizado\">a</mark> los que se refiere los apartados 4 y 5 del artículo 32, <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">indemnizables los daños producidos en el</mark> <mark class=\"m-plazo\">plazo de los cinco años anteriores a la fecha <u class=\"m-clave\">de</u> la publicación de la sentencia</mark> que declare <mark class=\"m-personalizado\">la inconstitucionalidad</mark> de la <mark class=\"m-destacable\">norma con rango de ley</mark> <mark class=\"m-personalizado\">o</mark> el carácter de <mark class=\"m-personalizado\">norma contraria al Derecho de la Unión</mark> Europea, <mark class=\"m-personalizado\"><u class=\"m-clave\">salvo</u> que la sentencia disponga otra</mark> cosa.</p><p data-ex=\"1\"><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">La indemnización <mark class=\"m-accion\">se calculará</mark> con arreglo a los <mark class=\"m-destacable\">criterios de valoración</mark> establecidos en <mark class=\"m-personalizado\">la</mark> <mark class=\"m-destacable\">legislación</mark> <mark class=\"m-autoridad\">fiscal,</mark> <mark class=\"m-personalizado\">de</mark> <mark class=\"m-destacable\">expropiación forzosa</mark> <mark class=\"m-personalizado\">y</mark> <mark class=\"m-destacable\">demás normas</mark> aplicables, ponderándose, <mark class=\"m-personalizado\">en su caso, las valoraciones</mark> predominantes en el <mark class=\"m-personalizado\">mercado.</mark> En los casos de <mark class=\"m-personalizado\">muerte o</mark> <mark class=\"m-destacable\">lesiones corporales</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">se</u></mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">tomar</mark> como referencia la valoración incluida en los baremos de <mark class=\"m-personalizado\">la normativa</mark> vigente en materia de <mark class=\"m-autoridad\">Seguros obligatorios y de la Seguridad Social.</mark></span></span></p><p data-ex=\"1\"><b>3.</b> <mark class=\"m-destacable\">La cuantía</mark> de la indemnización <mark class=\"m-personalizado\">se</mark> <span class=\"m-caja\"><mark class=\"m-accion\">calculará</mark></span> <mark class=\"m-personalizado\">con referencia al <u class=\"m-clave\">día</u> en que la <u class=\"m-clave\">lesión</u> efectivamente se produjo, sin perjuicio de su actualización a</mark> la fecha en que se ponga fin al procedimiento de responsabilidad <mark class=\"m-personalizado\">con arreglo al Índice de Garantía de la Competitividad, fijado por el</mark> Instituto Nacional <mark class=\"m-autoridad\">de</mark> <mark class=\"m-personalizado\">Estadística, y de los <u class=\"m-clave\">intereses</u></mark> que procedan <mark class=\"m-personalizado\">por demora</mark> en el pago de la indemnización fijada, los cuales <mark class=\"m-accion\">se exigirán</mark> <mark class=\"m-personalizado\">con arreglo</mark> a lo establecido en la <mark class=\"m-personalizado\">Ley</mark> 47/2003, de 26 de noviembre, <mark class=\"m-personalizado\"><u class=\"m-clave\">General</u> Presupuestaria, o,</mark> en su caso, a las normas presupuestarias de las <mark class=\"m-personalizado\">Comunidades Autónomas.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1847\">🎯 1 pregunta</mark></p><p data-ex=\"1\"><b>4.</b> La indemnización <span class=\"ex-plg\"><span class=\"ex-plg-t\">procedente <mark class=\"m-accion\">podrá sustituirse</mark> por una compensación en <mark class=\"m-destacable\">especie</mark> o ser abonada mediante pagos periódicos, cuando resulte más adecuado para lograr la reparación debida y convenga al <mark class=\"m-personalizado\">interés</mark></span></span> público, <mark class=\"m-personalizado\">siempre que</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1848\">exista acuerdo con el interesado</mark>.</p>"],["Artículo 36 — Exigencia de la responsabilidad patrimonial de las autoridades y personal al servicio de las Administraciones Públicas","<p><span class=\"ex-plg\"><span class=\"ex-plg-t\">(…) <b>2.</b> La Administración correspondiente, cuando hubiere indemnizado a los lesionados, <mark class=\"m-accion\">exigirá</mark> de oficio en vía administrativa <mark class=\"m-destacable\">de sus</mark> <mark class=\"m-autoridad\">autoridades y demás personal a su</mark> servicio la responsabilidad en que hubieran <mark class=\"m-personalizado\">incurrido por</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1576,11-ia-1849\">dolo, o culpa o negligencia graves, previa instrucción del correspondiente procedimiento</mark>.</span></span></p><p><b>a)</b> Alegaciones durante un plazo de quince días. b) <mark class=\"m-personalizado\">Práctica de las</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">pruebas</u></mark> admitidas <mark class=\"m-personalizado\">y cualesquiera otras</mark> que el <mark class=\"m-autoridad\">órgano</mark> competente estime oportunas durante un <mark class=\"m-plazo\">plazo de</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1603,11-ia-1850,11-ia-1883\">quince días. c) Audiencia durante un plazo de diez días. d) Formulación de la propuesta de resolución en un plazo de cinco</mark> <mark class=\"m-plazo\">días a contar desde la finalización del trámite de</mark> <mark class=\"m-autoridad\">audiencia</mark>. <mark class=\"m-destacable\">e) <u class=\"m-clave\">Resolución</u></mark> por el <mark class=\"m-autoridad\">órgano</mark> competente en el <mark class=\"m-plazo\">plazo de cinco días</mark>. (…)</p>"],["Artículo 39 — Portal de internet","<p>Se entiende por <mark class=\"m-destacable\">portal de</mark> <mark class=\"m-resp\" data-q=\"11-73\">internet el punto de acceso electrónico cuya titularidad corresponda a una Administración Pública, organismo público o entidad de Derecho</mark> Público</p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 41 — Actuación administrativa automatizada <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b><mark class=\"m-personalizado\">1.</mark></b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Se entiende</u></mark> por actuación <mark class=\"m-resp\" data-q=\"11-20,11-57,11-103,11-116,11-ia-1486\">administrativa automatizada, cualquier acto o actuación</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">realizada íntegramente <mark class=\"m-personalizado\">a través de medios</mark> electrónicos por una Administración Pública en el marco de un procedimiento administrativo y en la que no haya intervenido de forma directa <mark class=\"m-destacable\">un empleado público</mark></span></span> . <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1852\">🎯 1 pregunta</mark></p><p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">En caso de actuación administrativa automatizada <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">establecerse previamente</mark> <mark class=\"m-autoridad\">el órgano u órganos</mark> competentes, según los casos, para la definición de <mark class=\"m-personalizado\">las especificaciones</mark>, <mark class=\"m-personalizado\">programación</mark>, <mark class=\"m-personalizado\">mantenimiento</mark>, <mark class=\"m-personalizado\">supervisión y control de calidad y,</mark> en su caso, <mark class=\"m-personalizado\">auditoría</mark> del sistema de información y de su código fuente. Asimismo, <mark class=\"m-accion\">se indicará</mark> el <mark class=\"m-autoridad\">órgano</mark> que debe ser considerado <mark class=\"m-personalizado\">responsable</mark> a efectos <mark class=\"m-destacable\">de impugnación</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1853\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 42 — Sistemas de firma para la actuación administrativa automatizada <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\">En el ejercicio de la competencia en la actuación administrativa automatizada, <mark class=\"m-autoridad\">cada Administración</mark> Pública <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">determinar</mark> los supuestos de <mark class=\"m-personalizado\">utilización de los siguientes</mark> <mark class=\"m-destacable\">sistemas de firma</mark> <mark class=\"m-personalizado\">electrónica:</mark></span></span></p><p data-ex=\"1\"><b>a)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">Sello electrónico</mark> de Administración Pública, <mark class=\"m-autoridad\">órgano,</mark> organismo público o entidad de derecho <mark class=\"m-personalizado\">público, basado en</mark> <mark class=\"m-autoridad\">certificado electrónico reconocido o cualificado</mark> que reúna los <mark class=\"m-personalizado\">requisitos</mark> exigidos por la <mark class=\"m-personalizado\">legislación de firma electrónica.</mark></span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1857\">🎯 1 pregunta</mark></p><p data-ex=\"1\"><b>b)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">Código seguro de verificación</mark> <mark class=\"m-personalizado\">vinculado a la Administración</mark> Pública, <mark class=\"m-autoridad\">órgano,</mark> organismo público o entidad de Derecho Público, en los términos y condiciones establecidos, <mark class=\"m-personalizado\">permitiéndose</mark> en todo caso <mark class=\"m-personalizado\">la <u class=\"m-clave\">comprobación</u> de la integridad del documento mediante el</mark> <mark class=\"m-autoridad\">acceso a la sede electrónica</mark> correspondiente.</span></span> <mark class=\"m-resp ex-q\" data-q=\"11-196\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 46 — Archivo electrónico de documentos <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"1\"><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\"><u class=\"m-clave\">Todos</u></mark> <mark class=\"m-personalizado\">los documentos utilizados</mark> en las actuaciones administrativas <mark class=\"m-accion\">se almacenarán</mark> por medios <mark class=\"m-personalizado\">electrónicos,</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">salvo</u></mark> cuando <mark class=\"m-personalizado\">no sea posible.</mark></span></span></p><p data-ex=\"1\"><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Los documentos electrónicos</mark> que contengan <mark class=\"m-personalizado\">actos administrativos que afecten a derechos o intereses de los particulares</mark> <mark class=\"m-accion\">deberán</mark> <mark class=\"m-personalizado\">conservarse en soportes</mark> de esta naturaleza, ya sea en el mismo <mark class=\"m-personalizado\">formato</mark> a partir del que se originó el documento o en otro cualquiera que <mark class=\"m-personalizado\">asegure la identidad e integridad de la información necesaria para reproducirlo.</mark> <mark class=\"m-accion\">Se asegurará</mark> en <mark class=\"m-destacable\">todo caso</mark> la posibilidad de trasladar los datos a <mark class=\"m-personalizado\">otros formatos</mark> y soportes que <mark class=\"m-personalizado\">garanticen el acceso desde diferentes aplicaciones.</mark></span></span></p><p data-ex=\"1\"><b>3.</b> <mark class=\"m-destacable\">Los medios o soportes</mark> en que se almacenen documentos, <mark class=\"m-accion\">deberán contar</mark> <mark class=\"m-personalizado\">con medidas de seguridad,</mark> de acuerdo con lo previsto en el <mark class=\"m-autoridad\">Esquema Nacional de Seguridad,</mark> <mark class=\"m-personalizado\">que garanticen</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">la</u> integridad, autenticidad, <u class=\"m-clave\">confidencialidad,</u></mark> <mark class=\"m-personalizado\">calidad, <u class=\"m-clave\">protección</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">conservación</u></mark> de los documentos almacenados. En <mark class=\"m-personalizado\">particular,</mark> <mark class=\"m-accion\">asegurarán</mark> la <mark class=\"m-personalizado\"><u class=\"m-clave\">identificación de</u> los usuarios y el control de accesos,</mark> el cumplimiento de las <mark class=\"m-personalizado\">garantías</mark> previstas en la legislación de <mark class=\"m-personalizado\"><u class=\"m-clave\">protección</u> de datos,</mark> así como <mark class=\"m-personalizado\">la recuperación <u class=\"m-clave\">y conservación</u> a largo</mark> plazo de los documentos electrónicos producidos por las Administraciones Públicas que así lo requieran, <mark class=\"m-personalizado\">de acuerdo</mark> con las especificaciones sobre el <mark class=\"m-destacable\">ciclo <u class=\"m-clave\">de</u> vida</mark> <mark class=\"m-personalizado\">de los servicios y sistemas utilizados.</mark></p><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\">Artículo 46 bis. <mark class=\"m-destacable\">Ubicación de los sistemas de información y comunicaciones para el registro de datos.</mark></span></span></p><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\">Los sistemas de información y comunicaciones para la recogida, almacenamiento, procesamiento y gestión del <mark class=\"m-personalizado\">censo electoral, los padrones</mark> municipales de habitantes y <mark class=\"m-personalizado\">otros registros de población, datos</mark> <mark class=\"m-autoridad\">fiscales</mark> relacionados <mark class=\"m-personalizado\">con tributos</mark> propios o cedidos y datos de los usuarios <mark class=\"m-personalizado\">del sistema nacional de salud,</mark> así como los correspondientes <mark class=\"m-personalizado\">tratamientos de datos personales,</mark> <mark class=\"m-accion\">deberán</mark> <mark class=\"m-destacable\">ubicarse y prestarse dentro del territorio de la Unión Europea.</mark></span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1859\">🎯 1 pregunta</mark></p><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\">Los datos a que se refiere el apartado anterior <mark class=\"m-destacable\">no</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-destacable\">ser objeto de transferencia a un tercer país u organización internacional,</mark> con excepción de los que hayan sido objeto de una <mark class=\"m-personalizado\">decisión de adecuación de la</mark> <mark class=\"m-autoridad\">Comisión</mark> <mark class=\"m-personalizado\">Europea o cuando así</mark> lo exija el cumplimiento de las <mark class=\"m-personalizado\">obligaciones internacionales</mark> asumidas por el Reino de España.</span></span></p>"],["Artículo 47 — Definición y tipos de convenios","<p><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">Son convenios</mark> <mark class=\"m-personalizado\">los</mark> <mark class=\"m-destacable\">acuerdos <u class=\"m-clave\">con efectos</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">jurídicos</u> adoptados por las Administraciones</mark> Públicas, los organismos públicos y entidades de derecho público vinculados o dependientes <mark class=\"m-personalizado\">o las Universidades públicas <u class=\"m-clave\">entre</u> sí o con sujetos de derecho <u class=\"m-clave\">privado para un fin</u> común</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1861\">🎯 1 pregunta</mark></p><p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">No tienen la consideración de convenios</mark>, <mark class=\"m-personalizado\">los</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1860\">Protocolos Generales de Actuación o instrumentos similares que comporten meras declaraciones de intención de contenido general</mark> o que expresen la voluntad de las Administraciones y partes suscriptoras para actuar con un <mark class=\"m-personalizado\">objetivo común</mark>, <mark class=\"m-personalizado\">siempre que no <u class=\"m-clave\">supongan la</u> formalización de compromisos jurídicos concretos y exigibles</mark>.</span></span></p><p class=\"ex-mas\"><mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1863\">🎯 1 pregunta más de este artículo</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 48 — Requisitos de validez y eficacia de los convenios <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Las Administraciones Públicas</mark>, sus organismos públicos y entidades de derecho público vinculados o dependientes <span class=\"m-circulo\"><mark class=\"m-personalizado\">y</mark></span> <mark class=\"m-personalizado\">las Universidades públicas</mark>, en el ámbito de sus respectivas competencias, <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">suscribir convenios</mark> con sujetos de derecho público y privado, <mark class=\"m-personalizado\">sin</mark> que ello pueda <mark class=\"m-personalizado\">suponer cesión de la <u class=\"m-clave\">titularidad</u> de la</mark> competencia.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1864\">🎯 1 pregunta</mark></p><p><span class=\"ex-plg\"><span class=\"ex-plg-t\">(…) <b>4.</b> La gestión, justificación y resto de actuaciones relacionadas con <mark class=\"m-personalizado\">los gastos derivados de los convenios que incluyan compromisos financieros</mark> para la Administración Pública o cualquiera de sus organismos públicos o entidades de derecho público vinculados o dependientes que lo suscriban, así como con los fondos comprometidos en virtud de dichos convenios, <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">ajustarán</mark> <mark class=\"m-personalizado\">a lo dispuesto en la legislación presupuestaria</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1866\">🎯 1 pregunta</mark></p><p>(…) <b>8.</b> <mark class=\"m-personalizado\">Los convenios se</mark> <mark class=\"m-destacable\">perfeccionan</mark> <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"11-ia-1869\">por la prestación del consentimiento de las partes</mark></mark>. <mark class=\"m-destacable\">Los</mark> <mark class=\"m-plazo\">convenios</mark> suscritos <mark class=\"m-destacable\">por la</mark> <mark class=\"m-autoridad\">Administración General del Estado</mark> o alguno de sus organismos públicos o entidades de derecho público vinculados o dependientes <mark class=\"m-accion\">resultarán</mark> eficaces una vez inscritos, en el plazo de 5 <mark class=\"m-resp r-ia\" data-q=\"11-ia-1735,11-ia-1867,11-ia-1868\">días hábiles desde su formalización</mark>, <mark class=\"m-personalizado\">en el</mark> <mark class=\"m-autoridad\">Registro Electrónico estatal de Órganos e Instrumentos de Cooperación del sector público estatal</mark>, <mark class=\"m-autoridad\">al que se</mark> <mark class=\"m-personalizado\">refiere la disposición adicional séptima</mark>. <mark class=\"m-personalizado\">Asimismo</mark>, <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">publicados</mark> <mark class=\"m-plazo\">en el plazo de 10 días hábiles desde su formalización en el</mark> «<mark class=\"m-plazo\">Boletín Oficial del</mark> <mark class=\"m-autoridad\">Estado</mark>», <mark class=\"m-plazo\">sin perjuicio de su publicación facultativa en el boletín oficial de la comunidad autónoma o</mark> de la provincia que corresponda a la otra administración firmante.  <span class=\"ex-plg\"><span class=\"ex-plg-t\">9. Las normas del presente <mark class=\"m-destacable\">Capítulo no</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-destacable\">de aplicación a las encomiendas</mark> <mark class=\"m-plazo\">de gestión y los acuerdos</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">de terminación convencional de los</u> procedimientos</mark> administrativos.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1870\">🎯 1 pregunta</mark></p>"],["Artículo 49 — Contenido de los convenios","<p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><b><mark class=\"m-personalizado\">g)</mark></b> <mark class=\"m-personalizado\">El régimen de modificación del convenio</mark>. <mark class=\"m-personalizado\">A falta de regulación expresa</mark> la modificación del contenido del convenio <mark class=\"m-accion\">requerirá</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1872\">acuerdo unánime de los firmantes</mark>.</span></span></p><p><b>1.º</b> Los convenios <mark class=\"m-accion\">deberán</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1873,11-ia-1874\">tener una duración determinada, que no podrá ser superior a cuatro años, salvo que normativamente se prevea un plazo</mark> <mark class=\"m-autoridad\">superior</mark>.</p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 50 — Trámites preceptivos para la suscripción de convenios y sus efectos <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"1\"><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Sin perjuicio</mark> de las especialidades que <mark class=\"m-personalizado\">la legislación autonómica</mark> pueda prever, <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">necesario</mark> que el convenio <mark class=\"m-personalizado\">se acompañe</mark> de una <mark class=\"m-destacable\">memoria justificativa</mark> <mark class=\"m-personalizado\">donde se analice su necesidad y oportunidad, su impacto económico, el carácter no contractual</mark> de la actividad en cuestión, así <mark class=\"m-personalizado\">como el cumplimiento</mark> de lo previsto <mark class=\"m-personalizado\">en esta Ley.</mark></span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1875\">🎯 1 pregunta</mark></p><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\"><b><mark class=\"m-plazo\">2.</mark></b> <mark class=\"m-plazo\">Los convenios que</mark> <mark class=\"m-autoridad\">suscriba la Administración General del Estado o sus organismos</mark> públicos y entidades de derecho público vinculados o dependientes <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">acompañarán</mark> <mark class=\"m-personalizado\">además</mark> <mark class=\"m-destacable\">de:</mark></span></span></p><p data-ex=\"1\"><b><mark class=\"m-destacable\">a)</mark></b> <mark class=\"m-destacable\">El informe de su servicio jurídico, que</mark> <mark class=\"m-accion\">deberá</mark> <mark class=\"m-destacable\">emitirse en un plazo máximo de <mark class=\"m-resp\" data-q=\"11-198,11-ia-1876\">siete días hábiles desde su solicitud</mark>, transcurridos los cuales se</mark> <mark class=\"m-accion\">continuará</mark> <mark class=\"m-destacable\">la tramitación. En todo caso, dicho informe</mark> <mark class=\"m-accion\">deberá</mark> <mark class=\"m-destacable\">emitirse e incorporarse al expediente antes de proceder al perfeccionamiento del convenio. No</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-destacable\">necesario solicitar este informe cuando el convenio se ajuste</mark> a <mark class=\"m-destacable\">un modelo normalizado informado previamente por</mark> el servicio jurídico que corresponda. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1877\">🎯 1 pregunta</mark></p><p data-ex=\"1\"><b>b)</b> <mark class=\"m-autoridad\">Cualquier otro informe preceptivo que establezca la normativa aplicable, que</mark> <mark class=\"m-accion\">deberá</mark> <mark class=\"m-autoridad\">emitirse en un plazo máximo de siete días hábiles</mark> <mark class=\"m-personalizado\">desde su solicitud, transcurridos los cuales se</mark> <mark class=\"m-accion\">continuará</mark> <mark class=\"m-personalizado\">la tramitación.</mark> <mark class=\"m-destacable\">En cualquier caso,</mark> <mark class=\"m-accion\">deberán</mark> <mark class=\"m-destacable\">emitirse e incorporarse al expediente todos <u class=\"m-clave\">los informes preceptivos antes de proceder al perfeccionamiento del convenio.</u></mark></p><p data-ex=\"1\"><b><mark class=\"m-destacable\"><u class=\"m-clave\">c)</u></mark></b> La autorización previa del <mark class=\"m-autoridad\">Ministerio</mark> de Hacienda y Función Pública para su firma, modificación, prórroga y <mark class=\"m-destacable\">resolución</mark> por mutuo acuerdo entre <mark class=\"m-plazo\">las</mark> partes, <mark class=\"m-destacable\">que</mark> <mark class=\"m-accion\">deberá</mark> <mark class=\"m-destacable\">emitirse</mark> en un plazo máximo de siete días hábiles desde la solicitud, transcurridos los cuales <mark class=\"m-accion\">se continuará</mark> la tramitación. En todo caso dicha autorización <mark class=\"m-accion\">deberá emitirse</mark> e incorporarse al expediente antes de proceder al perfeccionamiento del convenio.</p><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Cuando el</mark> convenio a suscribir esté <mark class=\"m-personalizado\">excepcionado de la autorización</mark> a la que se refiere el párrafo anterior, <mark class=\"m-personalizado\">también</mark> lo <mark class=\"m-accion\">estará</mark> <mark class=\"m-personalizado\">del informe del</mark> <mark class=\"m-autoridad\">Ministerio de Política Territorial.</mark></span></span></p><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">No obstante, en todo caso,</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-autoridad\">preceptivo el informe del Ministerio de Política Territorial, respecto</mark> de los convenios que se suscriban entre la Administración General del <mark class=\"m-autoridad\">Estado</mark> y sus organismos públicos y entidades de derecho público vinculados o dependientes, con las Comunidades Autónomas o con Entidades Locales o con sus organismos públicos y entidades de derecho público vinculados o dependientes, <mark class=\"m-personalizado\">en los casos siguientes:</mark></span></span></p><p data-ex=\"1\"><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Convenios cuyo objeto sea la <mark class=\"m-personalizado\">cesión o adquisición</mark> de la titularidad de <mark class=\"m-personalizado\">infraestructuras por</mark> <mark class=\"m-autoridad\">la Administración General del Estado.</mark></span></span></p><p data-ex=\"1\"><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Convenios que tengan por objeto la <mark class=\"m-personalizado\">creación</mark> de <mark class=\"m-destacable\">consorcios</mark> previstos en el <mark class=\"m-personalizado\">artículo 123</mark> de esta ley.</span></span></p><p data-ex=\"1\"><b>d)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Cuando los <mark class=\"m-personalizado\">convenios plurianuales suscritos entre Administraciones Públicas incluyan aportaciones de fondos</mark> por parte <mark class=\"m-destacable\"><u class=\"m-clave\">del</u></mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">Estado</u></mark> para financiar actuaciones a ejecutar exclusivamente por parte de otra Administración Pública y el <mark class=\"m-autoridad\">Estado</mark> asuma, en el ámbito de sus competencias, los compromisos frente a terceros, la aportación del <mark class=\"m-autoridad\">Estado</mark> de <mark class=\"m-personalizado\">anualidades futuras</mark> <mark class=\"m-accion\">estará</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">condicionada</u> a la existencia de <u class=\"m-clave\">crédito</u> en los correspondientes presupuestos.</mark></span></span></p><p data-ex=\"1\"><b><mark class=\"m-personalizado\">e)</mark></b> Los convenios <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">interadministrativos</mark> <mark class=\"m-destacable\">suscritos con</mark> las Comunidades Autónomas <mark class=\"m-accion\">serán</mark> remitidos al Senado por <mark class=\"m-personalizado\">el</mark></span></span> <mark class=\"m-autoridad\">Ministerio</mark> de <mark class=\"m-resp r-ia\" data-q=\"11-ia-1879\">Política Territorial</mark>.</p>"],["Artículo 53 — Remisión de convenios al Tribunal de Cuentas","<p><b>1.</b> <mark class=\"m-plazo\">Dentro de los tres meses siguientes a la <u class=\"m-clave\">suscripción de cualquier</u> convenio cuyos compromisos</mark> <mark class=\"m-personalizado\">económicos asumidos <u class=\"m-clave\">superen los</u></mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1884\">600.000 euros</mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">estos</u></mark> <mark class=\"m-accion\">deberán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">remitirse electrónicamente al</u></mark> <mark class=\"m-autoridad\">Tribunal de Cuentas u órgano externo de fiscalización de la</mark> Comunidad <mark class=\"m-autoridad\">Autónoma</mark>, <mark class=\"m-personalizado\">según</mark> corresponda.</p>"],["Artículo 149 — Convocatoria de las reuniones de las Conferencias Sectoriales","<p><b>1.</b> Corresponde al <mark class=\"m-autoridad\">Ministro que presida la Conferencia Sectorial</mark> <mark class=\"m-accion\">acordar</mark> <mark class=\"m-destacable\">la convocatoria</mark> <mark class=\"m-personalizado\">de las</mark> reuniones <mark class=\"m-personalizado\">por</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1345,11-ia-1985,11-ia-1986,11-ia-1987\">iniciativa propia, al menos una vez al año, o cuando lo soliciten, al menos, la tercera parte de sus miembros. En este último caso, la solicitud</mark> <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">incluir la propuesta de orden del</mark> día.</p><p><b>3.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Cuando la conferencia sectorial hubiera de reunirse con el <mark class=\"m-personalizado\">objeto exclusivo de</mark> <mark class=\"m-destacable\">informar un proyecto normativo</mark>, <mark class=\"m-personalizado\">la convocatoria</mark>, <mark class=\"m-personalizado\">la constitución</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">y</mark></span> <mark class=\"m-personalizado\">adopción</mark> de acuerdos <mark class=\"m-accion\">podrá efectuarse</mark> por <mark class=\"m-personalizado\">medios <u class=\"m-clave\">electrónicos</u></mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">telefónicos o</u></mark> audiovisuales, que garanticen la intercomunicación entre ellos y la unidad de acto, tales como la videoconferencia o el correo electrónico, <mark class=\"m-personalizado\">entendiéndose los acuerdos adoptados en el lugar donde esté la</mark> <mark class=\"m-autoridad\">presidencia</mark>, de acuerdo con el procedimiento que se establezca en el reglamento de funcionamiento interno de la conferencia sectorial.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1988\">🎯 1 pregunta</mark></p>"],["Artículo 151 — Clases de decisiones de la Conferencia Sectorial","<p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><b><mark class=\"m-plazo\">a)</mark></b> Acuerdo: supone un <mark class=\"m-personalizado\">compromiso de actuación</mark> en el ejercicio de las <mark class=\"m-personalizado\">respectivas competencias</mark>. <mark class=\"m-personalizado\">Son de <u class=\"m-clave\">obligado</u> cumplimiento y directamente exigibles</mark> de acuerdo con lo previsto en la <mark class=\"m-personalizado\">Ley</mark> 29/1998, de 13 de julio, reguladora de la <mark class=\"m-personalizado\">Jurisdicción Contencioso-administrativa</mark>, <mark class=\"m-personalizado\">salvo</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1992\">para quienes hayan <mark class=\"m-personalizado\">votado en contra</mark> mientras no decidan suscribirlos</mark> con posterioridad. <mark class=\"m-personalizado\">El acuerdo</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">certificado en acta</mark>.</span></span></p><p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Cuando la Administración General del</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">ejerza funciones de coordinación</mark>, de acuerdo con el <mark class=\"m-personalizado\">orden constitucional de distribución de competencias</mark> del ámbito material respectivo, el Acuerdo que se adopte en la Conferencia Sectorial, y en el que <mark class=\"m-accion\">se incluirán</mark> los votos particulares que se hayan formulado, <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">de obligado cumplimiento</mark> para todas las Administraciones Públicas integrantes de la Conferencia Sectorial, <mark class=\"m-personalizado\"><u class=\"m-clave\">con independencia</u> del sentido de su voto</mark>, <mark class=\"m-personalizado\">siendo exigibles</mark> conforme a lo establecido en la Ley 29/1998, de 13 de julio. <mark class=\"m-personalizado\">El acuerdo</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">certificado en acta</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1993\">🎯 1 pregunta</mark></p><p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Recomendación</mark> <mark class=\"m-destacable\">salvo</mark> quienes hayan <mark class=\"m-personalizado\">votado en contra</mark> mientras no decidan suscribirla con posterioridad. <mark class=\"m-personalizado\">Si algún miembro se aparta</mark> de la Recomendación, <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">motivarlo e incorporar</mark> dicha justificación en el correspondiente <mark class=\"m-personalizado\">expediente</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1995\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 153 — Comisiones Bilaterales de Cooperación <span class=\"ex-sello\">EX</span> <span class=\"ex-sello ex-sello-r\">R48</span></div><div class=\"ex-fb\"><p data-ex=\"1\"><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Las Comisiones Bilaterales de Cooperación son <mark class=\"m-autoridad\">órganos</mark> de <mark class=\"m-personalizado\">cooperación de composición bilateral</mark> que <mark class=\"m-destacable\">reúnen,</mark> por un número <mark class=\"m-autoridad\">igual de representantes, a miembros del Gobierno, en representación</mark> de la <mark class=\"m-autoridad\">Administración General del Estado,</mark> <mark class=\"m-personalizado\">y</mark> miembros del <mark class=\"m-autoridad\">Consejo de Gobierno</mark> de <mark class=\"m-personalizado\">la Comunidad Autónoma</mark> <span class=\"m-caja\">o</span> <mark class=\"m-autoridad\">representantes</mark> de la Ciudad de <mark class=\"m-personalizado\">Ceuta</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">o</mark></span> de la <mark class=\"m-personalizado\">Ciudad de Melilla.</mark></span></span> <mark class=\"m-resp ex-q\" data-q=\"11-215\">🎯 1 pregunta</mark></p><p data-ex=\"1\"><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">Las Comisiones Bilaterales de Cooperación</mark> <mark class=\"m-personalizado\">ejercen funciones de <u class=\"m-clave\">consulta</u> y <u class=\"m-clave\">adopción</u> de acuerdos</mark> que tengan por <mark class=\"m-personalizado\">objeto la mejora de la coordinación</mark> entre las respectivas Administraciones en <mark class=\"m-personalizado\">asuntos que afecten</mark> de forma singular <mark class=\"m-personalizado\">a la Comunidad Autónoma,</mark> a la Ciudad de Ceuta o a la Ciudad de Melilla.</span></span></p><p data-ex=\"1\"><b>3.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Para el desarrollo de su actividad,</mark> las Comisiones Bilaterales de Cooperación <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">crear Grupos</mark> <mark class=\"m-destacable\">de trabajo</mark> <mark class=\"m-personalizado\">y</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">convocarse y</mark> <mark class=\"m-accion\">adoptar</mark> <mark class=\"m-destacable\">acuerdos</mark> por <mark class=\"m-personalizado\">videoconferencia o por medios electrónicos.</mark></span></span></p><p data-ex=\"1\" data-r=\"R48\"><span class=\"ex-sello ex-sello-r\">R48</span> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><b><mark class=\"m-personalizado\">4.</mark></b> Las decisiones adoptadas por las Comisiones Bilaterales de Cooperación <mark class=\"m-accion\">revestirán</mark> <mark class=\"m-personalizado\">la forma de</mark> <mark class=\"m-destacable\">Acuerdos y</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">de obligado cumplimiento, cuando así se prevea expresamente,</mark> para las dos Administraciones que lo suscriban y en ese <mark class=\"m-personalizado\">caso</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">exigibles conforme</mark> a lo establecido en <mark class=\"m-personalizado\">la Ley 29/1998, de 13 de julio.</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">El acuerdo</mark></span> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">certificado en</mark> acta.</span></span></p><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\"><b><mark class=\"m-personalizado\">5.</mark></b> <mark class=\"m-personalizado\">Lo previsto en este artículo</mark> <mark class=\"m-accion\">será</mark> de aplicación <mark class=\"m-personalizado\">sin perjuicio de</mark> las peculiaridades que, de acuerdo con las finalidades básicas previstas, se establezcan en los <mark class=\"m-personalizado\">Estatutos de Autonomía</mark> en materia de organización y funciones de <mark class=\"m-personalizado\">las comisiones bilaterales.</mark></span></span></p>"],["Artículo 3 — Otros sujetos obligados","<p><b>a)</b> Los <mark class=\"m-destacable\">partidos políticos</mark>, <mark class=\"m-personalizado\">organizaciones</mark> <mark class=\"m-destacable\">sindicales</mark> <mark class=\"m-personalizado\">y</mark> organizaciones <mark class=\"m-personalizado\">empresariales</mark>. b) Las <mark class=\"m-destacable\">entidades privadas que</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1213,11-ia-1240,11-ia-1313,11-ia-1333,11-ia-1832,11-ia-1895,11-ia-2032,11-ia-2033,11-ia-2170\">perciban durante el período de un año ayudas o subvenciones públicas en una cuantía superior a 100.000 euros o cuando al menos el 40 % del total de sus ingresos anuales tengan carácter de ayuda o subvención pública, siempre que alcancen como mínimo</mark> <mark class=\"m-destacable\">la cantidad de 5.000 euros</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2034\">🎯 1 pregunta</mark></p>"],["Artículo 5 — Principios generales <span class=\"ex-sello ex-sello-r\">R49</span>","<p>Cuando se trate <span class=\"ex-plg\"><span class=\"ex-plg-t\">de <mark class=\"m-personalizado\">entidades sin ánimo de lucro</mark> que persigan exclusivamente <mark class=\"m-destacable\">fines</mark> de <mark class=\"m-personalizado\">interés social o cultural</mark> y</span></span> cuyo <mark class=\"m-destacable\">presupuesto sea inferior a 50.</mark><mark class=\"m-resp\" data-q=\"11-65,11-ia-2040,11-ia-2155\">000 euros</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">el cumplimiento de las obligaciones derivadas de esta <mark class=\"m-personalizado\">Ley</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">realizarse utilizando los</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">medios</mark></span> <mark class=\"m-personalizado\">electrónicos</mark> puestos a su disposición por la Administración Pública de la que provenga la mayor parte de las ayudas o subvenciones públicas percibidas.</span></span>  (…)</p>"],["Artículo 6 — Información institucional, organizativa y de planificación","<p><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Los sujetos comprendidos</mark> en el ámbito de aplicación de este título <mark class=\"m-accion\">publicarán</mark> <mark class=\"m-personalizado\">información relativa a las</mark> <mark class=\"m-destacable\">funciones</mark> <mark class=\"m-personalizado\">que desarrollan</mark>, <mark class=\"m-personalizado\">la</mark> <mark class=\"m-destacable\">normativa</mark> <mark class=\"m-personalizado\">que les sea de aplicación</mark> <span class=\"m-caja\">así como a</span> su <mark class=\"m-personalizado\">estructura organizativa</mark>. <mark class=\"m-personalizado\">A estos</mark> efectos, <mark class=\"m-accion\">incluirán</mark> un <mark class=\"m-resp r-ia\" data-q=\"11-ia-2043\">organigrama actualizado que identifique a los responsables de los diferentes órganos y su perfil y trayectoria profesional</mark>.</span></span></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 7 — Información de relevancia jurídica <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\">Las <mark class=\"m-autoridad\">Administraciones Públicas,</mark> en el ámbito de sus competencias, <mark class=\"m-accion\">publicarán:</mark></span></span></p><p data-ex=\"1\"><b>a)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Las directrices, instrucciones, acuerdos, circulares o respuestas a consultas planteadas por los <mark class=\"m-personalizado\">particulares u otros</mark> <mark class=\"m-autoridad\">órganos</mark> en <mark class=\"m-personalizado\">la medida en que supongan una interpretación del Derecho o tengan efectos jurídicos.</mark></span></span></p><p data-ex=\"1\"><b>b)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">Los Anteproyectos de Ley y</mark> los proyectos de Decretos Legislativos cuya iniciativa les corresponda, cuando <mark class=\"m-personalizado\">se soliciten</mark> los dictámenes a los <mark class=\"m-autoridad\">órganos</mark> consultivos correspondientes.</span></span> En el caso <span class=\"ex-plg\"><span class=\"ex-plg-t\">en que no sea <mark class=\"m-personalizado\">preceptivo ningún dictamen la publicación se</mark> <mark class=\"m-accion\">realizará</mark> <mark class=\"m-destacable\"><mark class=\"m-resp\" data-q=\"11-216,11-ia-2047\">en el momento de su aprobación</mark>.</mark></span></span></p><p data-ex=\"1\"><b>c)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Los <mark class=\"m-destacable\">proyectos de Reglamentos</mark> cuya iniciativa les corresponda. <mark class=\"m-personalizado\">Cuando sea preceptiva la</mark> solicitud de <mark class=\"m-personalizado\">dictámenes, la publicación</mark> <mark class=\"m-accion\">se producirá</mark> una vez que estos <mark class=\"m-personalizado\">hayan sido solicitados a los</mark> <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-personalizado\">consultivos</mark> correspondientes <mark class=\"m-personalizado\">sin que ello suponga,</mark> necesariamente, la <mark class=\"m-personalizado\">apertura de un trámite de</mark> <mark class=\"m-autoridad\">audiencia</mark> <mark class=\"m-personalizado\">pública.</mark></span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2046,11-ia-2048\">🎯 2 preguntas</mark></p><p data-ex=\"1\"><b>d)</b> Las <mark class=\"m-destacable\">memorias e informes</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">que conformen los expedientes de elaboración de los textos normativos, en</span></span> particular, la <mark class=\"m-resp r-ia\" data-q=\"11-ia-2049\">memoria del análisis de impacto normativo</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">regulada por el Real Decreto 1083/2009, de 3 de julio.</span></span></p><p data-ex=\"1\"><b>e)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Los <mark class=\"m-destacable\">documentos</mark> que, conforme a la legislación sectorial vigente, <mark class=\"m-accion\">deban</mark> ser sometidos <mark class=\"m-personalizado\">a un período de información pública</mark> <mark class=\"m-plazo\">durante su tramitación.</mark></span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2050\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 8 — Información económica, presupuestaria y estadística <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b>a)</b> <mark class=\"m-destacable\">Todos los contratos</mark>, con indicación del objeto, duración, el importe de la licitación y de adjudicación, el procedimiento utilizado para su celebración, los instrumentos a través de los que, en su caso, se ha publicitado, el número de licitadores participantes en el procedimiento y la identidad del adjudicatario, así como las modificaciones del contrato. Igualmente <mark class=\"m-accion\">serán</mark> objeto de publicación las decisiones de desistimiento y renuncia de los contratos. La publicación de <span class=\"ex-plg\"><span class=\"ex-plg-t\">la información relativa a los contratos</span></span> menores <mark class=\"m-accion\">podrá realizarse</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-2051\">trimestralmente</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2053\">🎯 1 pregunta</mark></p><p>Además, <mark class=\"m-accion\">se publicará</mark> <mark class=\"m-personalizado\">información estadística sobre el porcentaje de participación en contratos adjudicados</mark> , tanto en relación con su número como en relación con su valor, de la categoría de microempresas, pequeñas y medianas empresas (<mark class=\"m-personalizado\">pymes</mark>), entendidas como tal según el anexo I del Reglamento (UE) n.º 651/2014 de la <mark class=\"m-autoridad\">Comisión,</mark> de 17 de junio de 2014, para cada uno de los procedimientos y tipologías previstas en la legislación de contratos del sector público. <mark class=\"m-destacable\">La publicación</mark> <mark class=\"m-personalizado\">de</mark> esta información <mark class=\"m-accion\">se realizará</mark> <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"11-ia-2052\">semestralmente</mark></mark>, <mark class=\"m-personalizado\">a</mark> partir <mark class=\"m-personalizado\">de un</mark> año de la publicación de la norma. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1310\">🎯 1 pregunta</mark></p><p><b>c)</b> Las subvenciones <span class=\"ex-plg\"><span class=\"ex-plg-t\">y ayudas públicas concedidas con</span></span> indicación de <mark class=\"m-resp r-ia\" data-q=\"11-ia-2054\">su importe, objetivo o finalidad y beneficiarios</mark>.</p><p><b>f)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Las retribuciones percibidas anualmente por los altos cargos y máximos responsables de las entidades incluidas en el ámbito de la aplicación de este título. Igualmente, <mark class=\"m-accion\">se harán</mark> públicas las indemnizaciones percibidas, en su caso, con ocasión del abandono del cargo.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2055\">🎯 1 pregunta</mark></p><p><b>h)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Las <mark class=\"m-destacable\">declaraciones</mark> <mark class=\"m-personalizado\">anuales de</mark> <mark class=\"m-destacable\">bienes y</mark> <mark class=\"m-personalizado\">actividades de los representantes locales</mark>, en los términos previstos en la Ley 7/1985, de 2 de abril, Reguladora de las Bases del Régimen Local. Cuando el reglamento no fije los términos en que han de hacerse públicas estas declaraciones <mark class=\"m-accion\">se aplicará</mark> lo dispuesto en la normativa de conflictos de intereses en el ámbito de la Administración General del <mark class=\"m-autoridad\">Estado.</mark> <mark class=\"m-personalizado\">En todo caso</mark>, <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">omitirán</mark> <mark class=\"m-personalizado\">los datos relativos a la localización concreta de los bienes inmuebles y se</mark> <mark class=\"m-accion\">garantizará</mark> <mark class=\"m-personalizado\">la privacidad y seguridad de sus titulares</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2056,11-ia-2149\">🎯 2 preguntas</mark></p><p>(…) <b>3.</b> <mark class=\"m-autoridad\">Las Administraciones Públicas</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">publicarán</mark> <mark class=\"m-personalizado\">la</mark> relación de</span></span> los <mark class=\"m-personalizado\">bienes inmuebles que sean de su propiedad o sobre los que ostenten algún</mark> <mark class=\"m-resp\" data-q=\"11-150,11-ia-2057\">derecho real</mark>.</p>"],["Artículo 9 — Control","<p><b>3.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">El <mark class=\"m-personalizado\">incumplimiento reiterado</mark> de las <mark class=\"m-destacable\">obligaciones</mark> de <mark class=\"m-destacable\">publicidad activa</mark> <mark class=\"m-personalizado\">reguladas</mark> en este <mark class=\"m-destacable\">capítulo</mark> <mark class=\"m-accion\">tendrá</mark> la <mark class=\"m-personalizado\">consideración</mark> de <mark class=\"m-resp r-ia\" data-q=\"11-ia-2060\">infracción grave</mark> a los <mark class=\"m-personalizado\">efectos de aplicación</mark> a sus <mark class=\"m-autoridad\">responsables</mark> del <mark class=\"m-personalizado\">régimen disciplinario previsto en la correspondiente normativa reguladora</mark>.</span></span> <mark class=\"m-resp ex-q\" data-q=\"11-223\">🎯 1 pregunta</mark></p>"],["Artículo 10 — Portal de la Transparencia","<p><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">La <mark class=\"m-autoridad\">Administración General del Estado</mark> <mark class=\"m-accion\">desarrollará</mark> un <mark class=\"m-destacable\">Portal</mark> de la <mark class=\"m-destacable\">Transparencia</mark>, <mark class=\"m-personalizado\">dependiente</mark> del <mark class=\"m-resp r-ia\" data-q=\"11-ia-2061\">Ministerio de la Presidencia</mark>, que <mark class=\"m-accion\">facilitará</mark> el <mark class=\"m-destacable\">acceso</mark> de los <mark class=\"m-autoridad\">ciudadanos</mark> a <u class=\"m-clave\">toda</u> la <mark class=\"m-destacable\">información</mark> a la que <mark class=\"m-accion\">se refieren</mark> los <mark class=\"m-personalizado\">artículos anteriores relativa a su ámbito de actuación</mark>.</span></span></p><p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">El <mark class=\"m-destacable\">Portal</mark> de la <mark class=\"m-destacable\">Transparencia</mark> <mark class=\"m-accion\">incluirá</mark>, en los <mark class=\"m-personalizado\">términos</mark> que <mark class=\"m-accion\">se establezcan</mark> <mark class=\"m-personalizado\">reglamentariamente</mark>, la <mark class=\"m-destacable\">información</mark> de la <mark class=\"m-autoridad\">Administración General del Estado</mark>, <mark class=\"m-personalizado\">cuyo</mark> <mark class=\"m-destacable\">acceso</mark> <mark class=\"m-accion\">se solicite</mark> con <mark class=\"m-personalizado\">mayor</mark> <mark class=\"m-destacable\">frecuencia</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2062\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 11 — Principios técnicos <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><span class=\"ex-plg\"><span class=\"ex-plg-t\">El <mark class=\"m-autoridad\">Portal de la Transparencia</mark> <mark class=\"m-accion\">contendrá</mark> <mark class=\"m-personalizado\">información publicada</mark> de acuerdo con las <mark class=\"m-personalizado\">prescripciones técnicas</mark> <mark class=\"m-accion\">que se establezcan</mark> <span class=\"m-caja\">reglamentariamente</span> que <mark class=\"m-accion\">deberán adecuarse</mark> a los siguientes <mark class=\"m-destacable\">principios</mark>:</span></span></p><p><b>a)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">Accesibilidad</mark>: <mark class=\"m-accion\">se proporcionará</mark> <mark class=\"m-personalizado\">información estructurada</mark> sobre los documentos y <span class=\"m-caja\">recursos</span> de información con vistas a <mark class=\"m-personalizado\">facilitar la identificación y búsqueda</mark> de la información.</span></span></p><p><b>b)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">Interoperabilidad</mark>: la información publicada <mark class=\"m-accion\">será</mark> conforme al Esquema Nacional de <mark class=\"m-autoridad\">Interoperabilidad</mark>, aprobado por <mark class=\"m-personalizado\">el Real Decreto 4/2010, de 8 enero</mark>, así como a las normas <mark class=\"m-personalizado\">técnicas de interoperabilidad</mark>.</span></span></p><p><b>c)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">Reutilización</mark>: <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">fomentará</mark> <mark class=\"m-personalizado\">que la información sea publicada en formatos que permita su reutilización</mark>, de acuerdo con lo previsto en <mark class=\"m-personalizado\">la Ley 37/2007,</mark> de 16 <mark class=\"m-personalizado\">de noviembre</mark>, sobre reutilización de <mark class=\"m-personalizado\">la información del sector público y en su normativa</mark> de desarrollo.</span></span></p><p class=\"ex-mas\"><mark class=\"m-resp ex-q\" data-q=\"11-36\">🎯 1 pregunta más de este artículo</mark></p>"],["Artículo 15 — Protección de datos personales","<p><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Si la información solicitada</mark> contuviera datos personales que <mark class=\"m-personalizado\">revelen la ideología</mark>, <mark class=\"m-personalizado\">afiliación sindical</mark>, <mark class=\"m-personalizado\">religión</mark> o creencias, el acceso <mark class=\"m-personalizado\">únicamente se</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">autorizar en</mark> caso de que se contase con <mark class=\"m-personalizado\">el</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1351,11-ia-1352,11-ia-2072,11-ia-2076\">consentimiento expreso y por escrito del afectado, a menos que dicho afectado hubiese hecho manifiestamente públicos los datos con anterioridad a que se solicitase</mark> el acceso.</span></span></p>"],["Artículo 16 — Acceso parcial","<p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">En</mark> los casos en que la aplicación de alguno de los <mark class=\"m-personalizado\">límites</mark> previstos en el artículo 14 no <mark class=\"m-personalizado\">afecte a la totalidad</mark> de la <mark class=\"m-resp r-ia\" data-q=\"11-ia-2022,11-ia-2073\">información, se concederá el acceso parcial previa omisión de la información afectada por el límite salvo que de ello resulte una información distorsionada o que carezca de sentido</mark>. En este caso, <mark class=\"m-accion\">deberá indicarse</mark> al solicitante que parte de la información ha sido omitida.</span></span></p>"],["Artículo 17 — Solicitud de acceso a la información","<p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><b><mark class=\"m-destacable\">3.</mark></b> <mark class=\"m-autoridad\">El solicitante</mark> <mark class=\"m-personalizado\">no está obligado a motivar su solicitud de acceso a</mark> la información. <mark class=\"m-personalizado\">Sin embargo</mark>, <mark class=\"m-accion\">podrá</mark> <mark class=\"m-destacable\">exponer los motivos</mark> por los que solicita la información <mark class=\"m-personalizado\">y que</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">ser tenidos en</mark> cuenta cuando se dicte la <mark class=\"m-personalizado\">resolución</mark>. No obstante, <mark class=\"m-destacable\">la ausencia</mark> <mark class=\"m-personalizado\">de</mark> <mark class=\"m-destacable\">motivación</mark> <mark class=\"m-personalizado\">no</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">por si sola causa de rechazo de la</mark> solicitud.</span></span> <mark class=\"m-resp ex-q\" data-q=\"11-224,11-ia-2075\">🎯 2 preguntas</mark></p><p><b>4.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Los <mark class=\"m-autoridad\">solicitantes de</mark> <mark class=\"m-personalizado\">información</mark> <mark class=\"m-accion\">podrán dirigirse</mark> a las <mark class=\"m-autoridad\">Administraciones Públicas</mark> <mark class=\"m-personalizado\">en cualquiera</mark> de las lenguas cooficiales del <mark class=\"m-autoridad\">Estado</mark> en el territorio en el que radique la Administración en cuestión.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2100\">🎯 1 pregunta</mark></p>"],["Artículo 18 — Causas de inadmisión","<p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">En el caso en que se <mark class=\"m-personalizado\">inadmita</mark> la solicitud por concurrir la causa prevista en la <mark class=\"m-personalizado\">letra d)</mark> del apartado anterior, el <mark class=\"m-autoridad\">órgano</mark> que acuerde la inadmisión <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">indicar</mark> en la resolución el <mark class=\"m-autoridad\">órgano</mark> que, a su juicio, <mark class=\"m-personalizado\">es competente</mark> para conocer de la solicitud.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2077\">🎯 1 pregunta</mark></p>"],["Artículo 19 — Tramitación <span class=\"ex-sello ex-sello-r\">R51</span>","<p><b>4.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Cuando la información objeto</mark> de la solicitud, <mark class=\"m-personalizado\">aun obrando</mark> en poder del sujeto al que se dirige, <mark class=\"m-personalizado\">haya sido elaborada o</mark> generada en su integridad o parte principal <mark class=\"m-personalizado\">por otro</mark>, <mark class=\"m-personalizado\">se le</mark> <mark class=\"m-accion\">remitirá</mark> <mark class=\"m-personalizado\">la solicitud</mark> a éste <mark class=\"m-personalizado\">para que decida</mark> sobre el acceso.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2080\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 20 — Resolución <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b>1.</b> La resolución en la que se conceda <mark class=\"m-destacable\">o deniegue el</mark> acceso <mark class=\"m-accion\">deberá</mark> <mark class=\"m-destacable\">notificarse</mark> al <mark class=\"m-personalizado\">solicitante y a los terceros</mark> <mark class=\"m-plazo\">afectados que así lo hayan solicitado en</mark> el plazo máximo de un mes <mark class=\"m-plazo\">desde la</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1462\">recepción de la solicitud por el órgano competente para resolver</mark>.</p><p><b>2.</b> <mark class=\"m-accion\">Serán</mark> <mark class=\"m-destacable\">motivadas</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">las <mark class=\"m-destacable\">resoluciones</mark> que <mark class=\"m-personalizado\">denieguen el acceso</mark>,</span></span> las que <mark class=\"m-resp r-ia\" data-q=\"11-ia-2082,11-ia-2085\">concedan el acceso parcial o a través de una modalidad distinta a la solicitada y las que permitan el acceso cuando haya habido oposición</mark> de un tercero. En este último supuesto, <mark class=\"m-accion\">se indicará</mark> expresamente al interesado que el acceso sólo <mark class=\"m-accion\">tendrá</mark> lugar cuando haya transcurrido el plazo del artículo 22.2.</p><p>(…) <b>4.</b> <mark class=\"m-autoridad\">Transcurrido el plazo</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">máximo para resolver sin que se haya dictado y notificado resolución</span></span> expresa se <mark class=\"m-resp r-ia\" data-q=\"11-ia-2083\">entenderá que la solicitud ha sido desestimada</mark>.</p><p><b>5.</b> <mark class=\"m-destacable\">Las resoluciones dictadas en</mark> <mark class=\"m-personalizado\">materia de acceso a la información pública son</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1338,11-ia-2084\">recurribles directamente ante la Jurisdicción Contencioso-administrativa, sin perjuicio de la posibilidad de interposición de la reclamación potestativa prevista</mark> en el artículo 24. (…)</p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 22 — Formalización del acceso <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b>1.</b> <mark class=\"m-destacable\">El acceso</mark> a la información <mark class=\"m-accion\">se realizará</mark> <mark class=\"m-resp\" data-q=\"11-197,11-ia-1812,11-ia-1858,11-ia-2016,11-ia-2071\">preferentemente por vía electrónica, salvo cuando no sea posible o el solicitante haya señalado expresamente otro medio. Cuando no pueda darse el acceso en el momento de la notificación</mark> <mark class=\"m-personalizado\">de</mark> la resolución <mark class=\"m-accion\">deberá</mark> <mark class=\"m-destacable\">otorgarse</mark>, <mark class=\"m-personalizado\">en cualquier caso</mark>, <mark class=\"m-personalizado\">en</mark> <mark class=\"m-autoridad\">un plazo</mark> no <mark class=\"m-autoridad\">superior a diez días</mark> .</p><p><b>2.</b> <mark class=\"m-personalizado\">Si ha existido</mark> <mark class=\"m-destacable\">oposición de tercero</mark>, <mark class=\"m-personalizado\">el acceso</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-1076,11-ia-1087,11-ia-1252,11-ia-1302,11-ia-1335,11-ia-2088,11-ia-2090\">sólo tendrá lugar cuando, habiéndose concedido dicho acceso, haya transcurrido el plazo para interponer recurso contencioso administrativo sin que se haya formalizado o haya sido resuelto confirmando</mark> el <span class=\"ex-plg\"><span class=\"ex-plg-t\">derecho a recibir la información.</span></span></p><p><b>4.</b> <mark class=\"m-personalizado\">El acceso</mark> a la información <mark class=\"m-accion\">será</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-2089\">gratuito. No obstante, la expedición de copias o la trasposición de la información a un formato diferente al original podrá dar lugar a la exigencia de exacciones en los términos</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">previstos en la Ley 8/1989, de 13 de abril, de Tasas y Precios Públicos, o, en su caso, conforme a la normativa autonómica o local que resulte aplicable.</span></span></p>"],["Artículo 30 — Sanciones","<p>(…) <b>4.</b> <mark class=\"m-destacable\">Los</mark> <mark class=\"m-personalizado\">sancionados</mark> por la <mark class=\"m-autoridad\">comisión</mark> de una infracción muy grave <mark class=\"m-accion\">serán</mark> destituidos del cargo que <mark class=\"m-resp r-ia\" data-q=\"11-ia-2109,11-ia-2110,11-ia-2113\">ocupen salvo que ya hubiesen cesado y no podrán ser nombrados para ocupar ningún puesto de alto cargo o asimilado durante un periodo de entre cinco y diez años</mark> <mark class=\"m-personalizado\">con</mark> arreglo a <mark class=\"m-personalizado\">los</mark> <mark class=\"m-destacable\">criterios</mark> previstos en el apartado siguiente. (…)</p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Competencia para imponer sanciones (art. 31.4 Ley 19/2013 · cuadro del temario)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-personalizado\">Competencia</mark> para la <mark class=\"m-destacable\">imposición</mark> de <u class=\"m-clave\">sanciones</u></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-autoridad\">Consejo de Ministros</mark>: <mark class=\"m-personalizado\">cuando el</mark> <mark class=\"m-personalizado\">alto cargo</mark> tenga <mark class=\"m-personalizado\">la condición</mark> de <mark class=\"m-personalizado\">miembro del</mark> <mark class=\"m-autoridad\">Gobierno</mark> o <mark class=\"m-autoridad\">Secretario de Estado</mark></div><div class=\"vis-rama\"><u class=\"m-clave\">Ministro</u> <mark class=\"m-personalizado\">de Hacienda y</mark> <mark class=\"m-autoridad\">Administraciones Públicas</mark>: <mark class=\"m-personalizado\">cuando el</mark> <mark class=\"m-destacable\">responsable</mark> <mark class=\"m-personalizado\">sea</mark> un <mark class=\"m-personalizado\">alto cargo de la Administración</mark> <mark class=\"m-autoridad\">General</mark> <mark class=\"m-autoridad\">del Estado</mark></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">Altos cargos</mark> de las CCAA <mark class=\"m-personalizado\">y Entidades</mark> <mark class=\"m-personalizado\">Locales</mark>: <mark class=\"m-autoridad\">los órganos</mark> que <mark class=\"m-personalizado\">tengan</mark> atribuidas estas <mark class=\"m-destacable\">funciones</mark> en <u class=\"m-clave\">aplicación</u> del <mark class=\"m-personalizado\">régimen disciplinario</mark> <mark class=\"m-personalizado\">propio</mark>, en <u class=\"m-clave\">su caso</u> el <mark class=\"m-autoridad\">Consejo de Gobierno</mark> de <mark class=\"m-personalizado\">la Comunidad Autónoma</mark> o el <mark class=\"m-autoridad\">Pleno</mark> de la Junta de <mark class=\"m-autoridad\">Gobierno de la</mark> <mark class=\"m-personalizado\">Entidad</mark> Local</div></div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 31 — <mark class=\"m-autoridad\">Órgano competente</mark> y <mark class=\"m-personalizado\">procedimiento</mark>: <mark class=\"m-resp ex-q\" data-q=\"11-182,11-ia-1714,11-ia-1744,11-ia-2114,11-ia-2116,11-ia-2175\">🎯 6 preguntas más de este artículo</mark>"],["Artículo 33 — Consejo de Transparencia y Buen Gobierno <span class=\"ex-sello ex-sello-r\">R53</span>","<p><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">Se crea el Consejo de Transparencia y Buen Gobierno</mark> como organismo público de los previstos en la disposición adicional décima de la Ley 6/1997, de 14 de abril, de Organización y Funcionamiento de la Administración General del <mark class=\"m-autoridad\">Estado.</mark> <mark class=\"m-accion\">Estará</mark> <mark class=\"m-destacable\">adscrito</mark> <mark class=\"m-autoridad\">al</mark> <mark class=\"m-resp r-ia\" data-q=\"11-ia-2121\">Ministerio de Hacienda y Administraciones Públicas</mark>.</span></span></p><p data-r=\"R53\"><span class=\"ex-sello ex-sello-r\">R53</span> <b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">El Consejo de Transparencia y Buen Gobierno</mark> <mark class=\"m-accion\">tiene</mark> <mark class=\"m-personalizado\">personalidad jurídica propia y plena capacidad de obrar</mark>. Actúa <mark class=\"m-personalizado\">con autonomía y plena independencia</mark> en el cumplimiento de sus fines.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2122\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 34 — Fines <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\">El <mark class=\"m-autoridad\">Consejo</mark> de Transparencia y Buen <mark class=\"m-autoridad\">Gobierno</mark> tiene por <mark class=\"m-destacable\">finalidad <u class=\"m-clave\">promover</u></mark> <mark class=\"m-personalizado\">la <u class=\"m-clave\">transparencia</u></mark> de la actividad pública, <mark class=\"m-destacable\">velar</mark> <mark class=\"m-personalizado\">por el cumplimiento de las obligaciones de publicidad,</mark> <mark class=\"m-destacable\">salvaguardar</mark> el ejercicio de <mark class=\"m-personalizado\"><u class=\"m-clave\">derecho</u> de acceso</mark> a la información pública <mark class=\"m-destacable\">y garantizar</mark> la observancia de las <mark class=\"m-personalizado\">disposiciones de buen</mark> <mark class=\"m-autoridad\">gobierno.</mark></span></span> <mark class=\"m-resp ex-q\" data-q=\"11-220,11-ia-2123\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 35 — Composición <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">El</mark> <mark class=\"m-autoridad\">Consejo</mark> <mark class=\"m-personalizado\">de Transparencia y Buen</mark> <mark class=\"m-autoridad\">Gobierno</mark> <mark class=\"m-accion\">estará</mark> <mark class=\"m-personalizado\">compuesto</mark> por los siguientes <mark class=\"m-autoridad\">órganos:</mark></span></span></p><p data-ex=\"1\"><b>a)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">La Comisión de Transparencia y Buen Gobierno.</mark> b) <mark class=\"m-autoridad\">El Presidente del Consejo</mark> de Transparencia y Buen <mark class=\"m-autoridad\">Gobierno</mark> <mark class=\"m-personalizado\">que lo</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">también</mark> de su <mark class=\"m-autoridad\">Comisión.</mark></span></span></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 36 — Comisión de Transparencia y Buen Gobierno <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b>a)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">El</mark> <mark class=\"m-autoridad\">Presidente</mark>. b) <mark class=\"m-personalizado\">Un Diputado</mark>. c) <mark class=\"m-personalizado\">Un Senador</mark>. d) <mark class=\"m-personalizado\">Un representante del</mark> <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-personalizado\">de Cuentas</mark>.</span></span> e) Un <mark class=\"m-personalizado\">representante del</mark> <mark class=\"m-autoridad\">Defensor</mark> <mark class=\"m-personalizado\">del</mark> <mark class=\"m-resp\" data-q=\"11-160,11-ia-2125,11-ia-2126\">Pueblo. f) Un representante de la Agencia Española de Protección de Datos. g) Un representante de la Secretaría de Estado de Administraciones Públicas. h) Un representante de la Autoridad Independiente de Responsabilidad Fiscal</mark>.</p><p><b>3.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">La condición</mark> de miembro de la <mark class=\"m-autoridad\">Comisión del Consejo de Transparencia</mark> y Buen <mark class=\"m-autoridad\">Gobierno</mark> <mark class=\"m-destacable\">no</mark> <mark class=\"m-accion\">exigirá</mark> dedicación exclusiva <mark class=\"m-accion\">ni dará</mark> derecho a remuneración con excepción de lo previsto en el artículo siguiente.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2127\">🎯 1 pregunta</mark></p><p><span class=\"ex-plg\"><span class=\"ex-plg-t\">ella, hayan sido creados por las Comunidades Autónomas en ejercicio de sus competencias.</span></span> A esta reunión <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">podrá</mark> ser convocado <mark class=\"m-personalizado\">un representante de</mark> <mark class=\"m-autoridad\">la Administración Local propuesto</mark></span></span> por la <mark class=\"m-resp r-ia\" data-q=\"11-ia-2128\">Federación <mark class=\"m-destacable\">Española de</mark> Municipios y Provincias</mark>.</p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 37 — Presidente del Consejo de Transparencia y Buen Gobierno <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p><b>1.</b> El <mark class=\"m-autoridad\">Presidente</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">del</mark> <mark class=\"m-autoridad\">Consejo</mark> <mark class=\"m-destacable\">de Transparencia y Buen</mark> <mark class=\"m-autoridad\">Gobierno</mark> <mark class=\"m-accion\">será</mark> nombrado</span></span> por un <mark class=\"m-resp\" data-q=\"11-225,11-ia-1145,11-ia-1376,11-ia-1715,11-ia-2129,11-ia-2131,11-ia-2162,11-ia-2176,11-ia-2230\">período no renovable de cinco años mediante Real Decreto, a propuesta del titular del Ministerio de Hacienda y Administraciones Públicas</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">entre personas de reconocido prestigio y competencia profesional previa comparecencia de la persona propuesta para <mark class=\"m-autoridad\">el cargo ante la Comisión correspondiente</mark> del Congreso de los Diputados.</span></span>  El Congreso, a <span class=\"ex-plg\"><span class=\"ex-plg-t\">través de la <mark class=\"m-autoridad\">Comisión</mark> competente</span></span> y por <mark class=\"m-resp r-ia\" data-q=\"11-ia-1128,11-ia-2025,11-ia-2081,11-ia-2130\">acuerdo adoptado por mayoría absoluta, deberá refrendar el nombramiento del candidato propuesto en el plazo de un mes</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-plazo\">natural desde la recepción de la correspondiente comunicación</mark></span></span> .</p><p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">El <mark class=\"m-autoridad\">Presidente del Consejo</mark> de Transparencia y Buen <mark class=\"m-autoridad\">Gobierno</mark> <mark class=\"m-accion\">cesará</mark> en <mark class=\"m-personalizado\">su</mark> cargo por la expiración de su <mark class=\"m-personalizado\">mandato</mark>, <mark class=\"m-personalizado\">a</mark> <mark class=\"m-destacable\">petición propia o por separación acordada por el</mark> <mark class=\"m-autoridad\">Gobierno</mark>, <mark class=\"m-destacable\">previa instrucción del</mark> correspondiente procedimiento por el titular del <mark class=\"m-autoridad\">Ministerio</mark> de Hacienda y Administraciones Públicas, por <mark class=\"m-destacable\">incumplimiento</mark> grave de sus obligaciones, incapacidad permanente para el ejercicio de su función, <mark class=\"m-destacable\">incompatibilidad</mark> <mark class=\"m-plazo\">sobrevenida</mark> <mark class=\"m-destacable\">o condena <u class=\"m-clave\">por</u> delito doloso</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2132\">🎯 1 pregunta</mark></p>"],["Artículo 38 — Funciones","<p><b>e)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Instar el inicio del procedimiento sancionador</mark> previsto en el título II de esta Ley. El <mark class=\"m-autoridad\">órgano</mark> competente <mark class=\"m-accion\">deberá motivar</mark>, en su caso, su decisión de no incoar el procedimiento.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2135,11-ia-2136\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 39 — Régimen jurídico <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"1\"><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">El <mark class=\"m-autoridad\">Consejo</mark> de Transparencia y Buen <mark class=\"m-autoridad\">Gobierno</mark> <mark class=\"m-accion\">se regirá,</mark> además de por lo dispuesto en esta Ley, por:</span></span></p><p data-ex=\"1\"><b>a)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Las disposiciones de la Ley 47/2003, de 26 de noviembre, General Presupuestaria, que le sean de aplicación. Anualmente <mark class=\"m-accion\">elaborará</mark> un anteproyecto de presupuesto con la estructura que establezca el <mark class=\"m-autoridad\">Ministerio</mark> de Hacienda y Administraciones Públicas para su elevación al <mark class=\"m-autoridad\">Gobierno</mark> y su posterior integración en los Presupuestos Generales del <mark class=\"m-autoridad\">Estado.</mark></span></span> <mark class=\"m-resp ex-q\" data-q=\"11-221,11-ia-2137\">🎯 2 preguntas</mark></p><p data-ex=\"1\"><b>b)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">El Real Decreto Legislativo 3/2011, de 14 de noviembre, por el que se aprueba el Texto Refundido de la Ley de Contratos del Sector Público.</span></span></p><p data-ex=\"1\"><b>c)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">La Ley 33/2003, de 3 de noviembre, del Patrimonio de las Administraciones Públicas, y, en lo no previsto en ella, por el Derecho privado en sus adquisiciones patrimoniales.</span></span></p><p data-ex=\"1\"><b>d)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">La Ley 7/2007, de 12 de abril, del Estatuto Básico del Empleado Público, y las demás normas aplicables al personal funcionario de la Administración General del <mark class=\"m-autoridad\">Estado,</mark> en materia de medios personales.</span></span></p><p data-ex=\"1\"><b>e)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">La Ley 30/1992, de 26 de noviembre, de Régimen Jurídico de las Administraciones Públicas y del Procedimiento Administrativo Común, y por la normativa que le sea de aplicación, en lo no dispuesto por esta Ley, cuando desarrolle sus funciones públicas.</span></span></p><p data-ex=\"1\"><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">El <mark class=\"m-autoridad\">Consejo de Ministros</mark> <mark class=\"m-accion\">aprobará</mark> mediante <mark class=\"m-destacable\">Real Decreto el Estatuto</mark> del <mark class=\"m-autoridad\">Consejo</mark> de Transparencia y Buen <mark class=\"m-autoridad\">Gobierno,</mark> en <mark class=\"m-personalizado\">el que se</mark> <mark class=\"m-accion\">establecerá</mark> <mark class=\"m-personalizado\">su organización, estructura, funcionamiento,</mark> así como todos <mark class=\"m-personalizado\">los aspectos que sean necesarios para el cumplimiento de sus funciones.</mark></span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2138\">🎯 1 pregunta</mark></p><p data-ex=\"1\"><b>3.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Con carácter general, los puestos de trabajo del <mark class=\"m-autoridad\">Consejo</mark> de Transparencia y Buen <mark class=\"m-autoridad\">Gobierno</mark> <mark class=\"m-accion\">serán</mark> desempeñados por funcionarios públicos de acuerdo con lo establecido en la Ley 7/2007, de 12 de abril, del Estatuto Básico del Empleado Público, y las normas de función pública aplicables al personal funcionario de la Administración General del <mark class=\"m-autoridad\">Estado.</mark> El personal laboral <mark class=\"m-accion\">podrá desempeñar</mark> puestos de trabajo que se ajusten a la normativa de función pública de la Administración General del <mark class=\"m-autoridad\">Estado.</mark> Asimismo, el personal que pase a prestar servicios en el <mark class=\"m-autoridad\">Consejo</mark> de Transparencia y Buen <mark class=\"m-autoridad\">Gobierno</mark> mediante los procedimientos de provisión previstos en la Administración General del <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-accion\">mantendrá</mark> la condición <mark class=\"m-personalizado\">de personal</mark> funcionario o <mark class=\"m-personalizado\">laboral,</mark> de acuerdo con la legislación aplicable.</span></span></p><p data-ex=\"1\"><b>4.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">El <mark class=\"m-autoridad\">Consejo de Transparencia y Buen Gobierno</mark> <mark class=\"m-accion\">contará</mark> para el cumplimiento de sus <mark class=\"m-destacable\">fines</mark> con los siguientes <mark class=\"m-destacable\">bienes y medios económicos:</mark></span></span></p><p data-ex=\"1\"><b>a)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Las</mark> <mark class=\"m-destacable\">asignaciones</mark> que se establezcan <mark class=\"m-plazo\">anualmente con</mark> cargos a <mark class=\"m-personalizado\">los Presupuestos Generales</mark> del <mark class=\"m-autoridad\">Estado.</mark></span></span></p><p data-ex=\"1\"><b>b)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Los <u class=\"m-clave\">bienes</u></mark> <mark class=\"m-destacable\">y valores</mark> que constituyan <mark class=\"m-personalizado\">su patrimonio,</mark> así como los <mark class=\"m-destacable\">productos</mark> <mark class=\"m-personalizado\">y</mark> <mark class=\"m-destacable\">rentas</mark> del mismo.</span></span></p><p data-ex=\"1\"><b>c)</b> Cualesquiera <mark class=\"m-personalizado\">otros que legalmente puedan serle atribuidos.</mark></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 40 — Relaciones con las Cortes Generales <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p data-ex=\"1\"><span class=\"ex-plg\"><span class=\"ex-plg-t\">El <mark class=\"m-autoridad\">Consejo</mark> de Transparencia y Buen <mark class=\"m-autoridad\">Gobierno</mark> <mark class=\"m-accion\">elevará</mark> anualmente a las Cortes Generales una memoria sobre el desarrollo de sus actividades y sobre el grado de cumplimiento de las disposiciones establecidas en esta Ley. El <mark class=\"m-autoridad\">Presidente del Consejo</mark> de Transparencia y Buen <mark class=\"m-autoridad\">Gobierno</mark> <mark class=\"m-accion\">comparecerá</mark> ante la <mark class=\"m-autoridad\">Comisión</mark> correspondiente para dar cuenta de tal memoria, así como cuantas veces sea requerido para ello.</span></span> <mark class=\"m-resp ex-q\" data-q=\"11-222,11-ia-2140\">🎯 2 preguntas</mark></p>"],["Artículo 3 — Objetivos","<p>Las medidas que <span class=\"ex-plg\"><span class=\"ex-plg-t\">se adopten en aplicación de este real decreto <mark class=\"m-accion\">tendrán</mark> como objetivo principal, de conformidad con los principios contenidos tanto en la Directiva 89/391/CEE como en la Ley 31/1995, de 8 de noviembre, la promoción de la mejora</span></span> de las <mark class=\"m-resp\" data-q=\"11-230,11-ia-2164,11-ia-2184\">condiciones del servicio y tratarán de elevar el nivel de protección de la seguridad y la salud del personal</mark> al que se dirigen.</p>"],["Artículo 15 — Inspección y control","<p>La Inspección de <span class=\"ex-plg\"><span class=\"ex-plg-t\">Personal y Servicios de Seguridad</span></span> de la <mark class=\"m-resp\" data-q=\"11-235,11-ia-1281,11-ia-2044,11-ia-2223,11-ia-2227\">Secretaría de Estado de Seguridad realizará las funciones de inspección y control externo de las actividades de los órganos citados en el párrafo anterior. A estos efectos, el Servicio de Prevención le remitirá una copia de la memoria anual</mark> que elabore. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-1336\">🎯 1 pregunta</mark></p><p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Si en la realización de tales inspecciones</mark> y controles <mark class=\"m-personalizado\">se detectara la existencia de situaciones de</mark> <mark class=\"m-destacable\">grave e inminente</mark> <mark class=\"m-personalizado\">riesgo para la seguridad</mark> <mark class=\"m-destacable\">y la salud</mark>, que no deban <mark class=\"m-personalizado\">ser asumidas</mark> en virtud de la <mark class=\"m-personalizado\">naturaleza</mark> de las funciones que se realizan, <mark class=\"m-accion\">se comunicará</mark> urgentemente a la <mark class=\"m-resp r-ia\" data-q=\"11-ia-2224\">subdirección general competente</mark> para adoptar las medidas necesarias para su corrección. De las demás deficiencias observadas <mark class=\"m-accion\">se elevará</mark> informe a la subdirección general competente, por conducto del <mark class=\"m-autoridad\">Servicio de Prevención</mark>, con las <mark class=\"m-destacable\">recomendaciones</mark> que estimen convenientes para su solución.</span></span></p></div></div><div class=\"ex-ficha ex-of\"><div class=\"ex-fh\">Artículo 16 — Procedimiento para el establecimiento de medidas correctoras <span class=\"ex-sello\">EX</span></div><div class=\"ex-fb\"><p>De esa propuesta <mark class=\"m-accion\">se dará</mark> traslado <mark class=\"m-autoridad\">al</mark> <mark class=\"m-resp\" data-q=\"11-48,11-101,11-ia-1922,11-ia-1997,11-ia-2008\">Director General de la Guardia Civil</mark>, a través del <mark class=\"m-autoridad\">Servicio</mark> de Prevención <mark class=\"m-autoridad\">de</mark> la Dirección General de la Guardia Civil, que <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">formular</mark> <mark class=\"m-destacable\">alegaciones</mark> en el plazo de 30 días hábiles desde su notificación.</p><p><mark class=\"m-personalizado\">Si</mark> <mark class=\"m-destacable\">no</mark> <mark class=\"m-personalizado\">se formulasen</mark> <mark class=\"m-destacable\">alegaciones</mark> en el plazo señalado en el párrafo anterior, por no mantener discrepancias sobre la existencia de las anomalías en materia de prevención, ni sobre las medidas precisas para su subsanación, <mark class=\"m-personalizado\">la propuesta de requerimiento</mark> <mark class=\"m-accion\">adquirirá</mark> <mark class=\"m-personalizado\">automáticamente</mark> <mark class=\"m-destacable\">carácter definitivo</mark>. En estos casos, <mark class=\"m-autoridad\">el Director General de la Guardia Civil</mark> <mark class=\"m-accion\">encomendará</mark> <mark class=\"m-autoridad\">al Servicio de Prevención</mark> citado <mark class=\"m-personalizado\">la realización de los trámites necesarios para que las medidas requeridas se lleven a cabo</mark>. <mark class=\"m-personalizado\">Realizada la</mark> <mark class=\"m-autoridad\">subsanación</mark>, <mark class=\"m-autoridad\">el Servicio de Prevención</mark> <mark class=\"m-accion\">dará</mark> <mark class=\"m-autoridad\">cuenta a la Inspección de Personal y Servicios de Seguridad de la Secretaría de Estado de Seguridad</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"11-ia-2226\">🎯 1 pregunta</mark></p><p>En el caso <span class=\"ex-plg\"><span class=\"ex-plg-t\">de discrepancias con la propuesta de requerimiento, <mark class=\"m-personalizado\">a la vista de las alegaciones</mark> formuladas por la Dirección General</span></span> <mark class=\"m-autoridad\">de la Guardia Civil en el referido plazo de</mark> <mark class=\"m-destacable\">30</mark> <mark class=\"m-resp\" data-q=\"11-46,11-117,11-ia-2225\">días hábiles</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">la Inspección de Personal y Servicios de Seguridad <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">elevar una propuesta de requerimiento definitivo al</mark> <mark class=\"m-autoridad\">Secretario de Estado</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">de</u></mark> Seguridad, <mark class=\"m-personalizado\">quien,</mark> previos los informes que estime oportunos, <mark class=\"m-accion\">dictará</mark> <mark class=\"m-plazo\">la</mark> resolución procedente.</span></span></p>"]];
